window.MG_LAZY_DATA["data/lazy/owner-courses/b226-16404ab663622466.json"]={sha256:"16404ab663622466759f1324ef2a9921b1e7baf6abc4c6a44f068583fc744792",value:{"id":"b226","category":"water","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v7-panama-gates","v7-panama-original","v7-panama-visitor","v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"title":"巴拿馬運河擴建新船閘","titleEn":"Panama Canal expansion locks","summary":"透過 24 個概念工序認識三階船閘、節水池、滾動閘門、土建與控制介面，連結通航能力、淡水資源與維護證據。","summaryEn":"Use 24 conceptual steps to connect three-chamber locks, water-saving basins, rolling gates and civil-control interfaces with navigation, freshwater and maintenance evidence.","scope":"以公開一次資料為背景的原創工程判讀課程；每步在紙上或數位示意模型中完成。自設數值、構形與工序不得當成原工程的設計、施工、設備操作或驗收程序。","scopeEn":"Original engineering interpretation exercises grounded in public primary sources. Complete each step on paper or in a schematic digital model. Invented values, geometry and sequences are not the original project’s design, construction, operating or acceptance procedures.","diagram":{"type":"water","labels":["需求與場址","結構與介面","施工狀態","驗證與維護"],"labelsEn":["Requirements and site","Structures and interfaces","Construction states","Verification and maintenance"],"original":true,"notToScale":true},"stepCount":64,"estimatedMinutes":1600,"stages":[{"id":"b226-stage01","order":1,"title":"通航需求與水量邊界","titleEn":"Navigation requirements and water balance","description":"以六個相互銜接的練習完成「通航需求與水量邊界」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on navigation requirements and water balance, retaining assumptions, diagrams and evidence.","steps":[{"id":"b226-v7-01","sequence":1,"order":1,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":[],"title":"畫出兩洋與湖泊的高程關係","titleEn":"Map ocean and lake level relationships","objective":"理解船閘如何連接不同水位。","objectiveEn":"Understand how locks connect different water levels.","instruction":"1. 畫海洋、閘室及加通湖三類區域；2. 用高程線區分水面；3. 將船移動路線與水移動路線分色。","instructionEn":"1. Draw ocean, lock chambers and Gatun Lake; 2. distinguish water levels with elevation lines; 3. separate vessel and water routes by color.","observation":"船的前進方向與水流方向不是必然相同。","observationEn":"Vessel direction and water-flow direction are not necessarily the same.","failure":"船閘是把海水連續向前推動船舶的單向水管。","failureEn":"A lock is a one-way pipe continuously pushing ships forward with seawater.","check":"提交含兩類路徑和水位基準的概念剖面。","checkEn":"Submit a conceptual section with two route types and a water-level datum.","knowledge":[{"id":"b226-v7-01-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"浮船的升降依靠所在水面的變化；閘室是調整水位的空間。","textEn":"A floating vessel rises or falls with its water surface; a lock chamber provides the changing-level space."},{"id":"b226-v7-01-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"水位圖描述功能概念，不是實際閘門開閉或通航程序。","textEn":"The level diagram explains function and is not an actual gate or transit procedure."}],"quiz":{"question":"審查「畫出兩洋與湖泊的高程關係」時，哪個判讀有根據？","questionEn":"When reviewing “Map ocean and lake level relationships”, which interpretation is justified?","options":["船的前進方向與水流方向不是必然相同。","船閘是把海水連續向前推動船舶的單向水管。","船舶高度由閘門馬達直接托舉，不受閘室水面影響。"],"optionsEn":["Vessel direction and water-flow direction are not necessarily the same.","A lock is a one-way pipe continuously pushing ships forward with seawater.","Gate motors directly lift vessel elevation independently of chamber water level."],"answer":0,"explanation":"浮船的升降依靠所在水面的變化；閘室是調整水位的空間。 水位圖描述功能概念，不是實際閘門開閉或通航程序。","explanationEn":"A floating vessel rises or falls with its water surface; a lock chamber provides the changing-level space. The level diagram explains function and is not an actual gate or transit procedure."}},{"id":"b226-v7-02","sequence":2,"order":2,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-01"],"title":"比較原船閘與擴建船閘","titleEn":"Compare original and expanded locks","objective":"避免把兩代設備與尺寸混用。","objectiveEn":"Avoid mixing two generations of equipment and dimensions.","instruction":"1. 分別建立原閘與新閘資料卡；2. 標示人字閘門與滾動閘門；3. 記錄每個尺寸所描述的是閘室還是船舶。","instructionEn":"1. Create separate original-lock and expanded-lock records; 2. distinguish miter and rolling gates; 3. identify whether each dimension describes chamber or vessel.","observation":"閘室尺寸與可通航船舶限制不是完全相同的量。","observationEn":"Chamber dimensions and permitted vessel limits are not identical quantities.","failure":"把新閘室寬度直接當成任何情境下的允許船寬。","failureEn":"Treat new-chamber width as the permissible vessel beam in every circumstance.","check":"輸出含設備世代與資料邊界的比較表。","checkEn":"Provide a comparison with equipment generation and data boundaries.","knowledge":[{"id":"b226-v7-02-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"擴建工程增加新的通航設施；原閘與新閘採用不同閘門及水管理配置。","textEn":"The expansion added facilities with gate and water-management arrangements different from the original locks."},{"id":"b226-v7-02-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"船舶限制需額外考慮通航要求，不能只從土建空間推算。","textEn":"Vessel limits involve navigation requirements beyond the physical civil-work space."}],"quiz":{"question":"審查「比較原船閘與擴建船閘」時，哪個判讀有根據？","questionEn":"When reviewing “Compare original and expanded locks”, which interpretation is justified?","options":["把新閘室寬度直接當成任何情境下的允許船寬。","閘室尺寸與可通航船舶限制不是完全相同的量。","原運河人字門與新閘滾動門具有相同運動幾何。"],"optionsEn":["Treat new-chamber width as the permissible vessel beam in every circumstance.","Chamber dimensions and permitted vessel limits are not identical quantities.","Original miter gates and new rolling gates have identical movement geometry."],"answer":1,"explanation":"擴建工程增加新的通航設施；原閘與新閘採用不同閘門及水管理配置。 船舶限制需額外考慮通航要求，不能只從土建空間推算。","explanationEn":"The expansion added facilities with gate and water-management arrangements different from the original locks. Vessel limits involve navigation requirements beyond the physical civil-work space."}},{"id":"b226-v7-03","sequence":3,"order":3,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-02"],"title":"拆出三階閘室系統","titleEn":"Decompose the three-chamber system","objective":"辨識單一閘室與整組船閘的關係。","objectiveEn":"Distinguish one chamber from a complete lock flight.","instruction":"1. 串接三個概念閘室；2. 標出相鄰水位邊界；3. 列出每個邊界需協調的水力及設備資訊。","instructionEn":"1. Connect three conceptual chambers; 2. mark adjacent water-level boundaries; 3. list hydraulic and equipment information needed at each boundary.","observation":"一個閘室的狀態可能改變相鄰區的可用條件。","observationEn":"The state of one chamber can affect conditions available to neighboring sections.","failure":"三個閘室可以忽略共同邊界而各自獨立任意運作。","failureEn":"Three chambers can operate arbitrarily and independently without shared boundaries.","check":"繳交三室及四個邊界的系統圖。","checkEn":"Provide a three-chamber diagram with four boundaries.","knowledge":[{"id":"b226-v7-03-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"串聯系統共享水位與通航介面，局部功能成立不代表整組時序相容。","textEn":"Series systems share level and navigation interfaces; local function does not establish compatible system timing."},{"id":"b226-v7-03-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本圖只表達依賴關係，不給出真實操作順序或設定值。","textEn":"The diagram expresses dependencies without real operating sequences or settings."}],"quiz":{"question":"審查「拆出三階閘室系統」時，哪個判讀有根據？","questionEn":"When reviewing “Decompose the three-chamber system”, which interpretation is justified?","options":["三個閘室可以忽略共同邊界而各自獨立任意運作。","相鄰閘室的水位邊界對彼此沒有影響。","一個閘室的狀態可能改變相鄰區的可用條件。"],"optionsEn":["Three chambers can operate arbitrarily and independently without shared boundaries.","Adjacent chamber-level boundaries have no mutual effect.","The state of one chamber can affect conditions available to neighboring sections."],"answer":2,"explanation":"串聯系統共享水位與通航介面，局部功能成立不代表整組時序相容。 本圖只表達依賴關係，不給出真實操作順序或設定值。","explanationEn":"Series systems share level and navigation interfaces; local function does not establish compatible system timing. The diagram expresses dependencies without real operating sequences or settings."}},{"id":"b226-v7-04","sequence":4,"order":4,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-03"],"title":"建立一個完整的水量邊界","titleEn":"Define a complete water-balance boundary","objective":"把閘室、節水池與外部水源放入守恆框架。","objectiveEn":"Place chambers, saving basins and external water in a conservation framework.","instruction":"1. 選定包住閘室與節水池的邊界；2. 列出進入、流出及儲水變化；3. 用自設體積核對平衡並標示未計入項。","instructionEn":"1. Enclose a chamber and its basins in a boundary; 2. list inflow, outflow and storage change; 3. reconcile invented volumes and identify omitted terms.","observation":"內部回用流量不應再次計為從湖泊新增取水。","observationEn":"Internal reuse should not be counted again as new withdrawal from the lake.","failure":"把每一段內部水流都加進外部耗水量。","failureEn":"Add every internal transfer to external water consumption.","check":"提交一次守恆計算與明確的系統邊界。","checkEn":"Submit one conservation calculation with an explicit system boundary.","knowledge":[{"id":"b226-v7-04-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"水量守恆取決於邊界定義，內部轉移在整體帳中應相互抵消。","textEn":"Water conservation depends on boundary definition; internal transfers cancel in the overall balance."},{"id":"b226-v7-04-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"自設例子不對應真實航次用水，實況還需水位及營運資料。","textEn":"The invented example is not real transit consumption, which requires level and operating data."}],"quiz":{"question":"審查「建立一個完整的水量邊界」時，哪個判讀有根據？","questionEn":"When reviewing “Define a complete water-balance boundary”, which interpretation is justified?","options":["內部回用流量不應再次計為從湖泊新增取水。","把每一段內部水流都加進外部耗水量。","內部轉移與外部取水在任何邊界下都是同一項。"],"optionsEn":["Internal reuse should not be counted again as new withdrawal from the lake.","Add every internal transfer to external water consumption.","Internal transfer and external withdrawal are identical under every boundary definition."],"answer":0,"explanation":"水量守恆取決於邊界定義，內部轉移在整體帳中應相互抵消。 自設例子不對應真實航次用水，實況還需水位及營運資料。","explanationEn":"Water conservation depends on boundary definition; internal transfers cancel in the overall balance. The invented example is not real transit consumption, which requires level and operating data."}},{"id":"b226-v7-05","sequence":5,"order":5,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-04"],"title":"辨認節水比例的分母","titleEn":"Identify the denominator in a saving ratio","objective":"區分回用比例、耗水差異與總取水。","objectiveEn":"Distinguish reuse fraction, consumption difference and total withdrawal.","instruction":"1. 寫出原始取水及回用的假想數據；2. 用兩個不同分母計算百分比；3. 說明為何不能把百分比直接相加。","instructionEn":"1. Write hypothetical withdrawal and reuse values; 2. calculate percentages using two denominators; 3. explain why those percentages cannot simply be added.","observation":"節水百分比需要交代比較對象與分母才具有意義。","observationEn":"A saving percentage needs a comparison basis and denominator to be meaningful.","failure":"兩份資料都寫節水就可把百分比相加得到總效果。","failureEn":"Two reported saving percentages can be added to obtain total benefit.","check":"輸出每個百分比的公式、分母及適用範圍。","checkEn":"Provide a formula, denominator and scope for each percentage.","knowledge":[{"id":"b226-v7-05-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"回用同一水體與減少外部取水是相關但不相同的指標。","textEn":"Reusing water and reducing external withdrawal are related but distinct metrics."},{"id":"b226-v7-05-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"官方發表的回用性能應連同測試或設計背景閱讀，不能推成每次航行保證。","textEn":"Published reuse performance needs its design or test context and is not a guarantee for every transit."}],"quiz":{"question":"審查「辨認節水比例的分母」時，哪個判讀有根據？","questionEn":"When reviewing “Identify the denominator in a saving ratio”, which interpretation is justified?","options":["兩份資料都寫節水就可把百分比相加得到總效果。","節水百分比需要交代比較對象與分母才具有意義。","同樣百分比在不同分母下代表相同節水體積。"],"optionsEn":["Two reported saving percentages can be added to obtain total benefit.","A saving percentage needs a comparison basis and denominator to be meaningful.","The same percentage under different denominators means the same saved volume."],"answer":1,"explanation":"回用同一水體與減少外部取水是相關但不相同的指標。 官方發表的回用性能應連同測試或設計背景閱讀，不能推成每次航行保證。","explanationEn":"Reusing water and reducing external withdrawal are related but distinct metrics. Published reuse performance needs its design or test context and is not a guarantee for every transit."}},{"id":"b226-v7-06","sequence":6,"order":6,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-05"],"title":"審查通航與水資源需求","titleEn":"Review navigation and water-resource needs","objective":"理解航運服務與流域其他用途的共同依賴。","objectiveEn":"Understand shared dependence of shipping and other watershed uses.","instruction":"1. 畫通航、居民用水及湖泊蓄水三個需求節點；2. 連到共同水源；3. 列出一項增加通航能力仍不能回答的資源問題。","instructionEn":"1. Draw navigation, public-water and storage demand nodes; 2. connect them to shared water; 3. identify a resource question increased navigation capacity cannot answer.","observation":"更大的船閘不能單獨保證任何乾旱條件下都有足夠淡水。","observationEn":"Larger locks alone cannot guarantee sufficient freshwater under every drought condition.","failure":"增加閘室尺寸會自動增加流域可用水量。","failureEn":"Increasing chamber size automatically increases available watershed water.","check":"繳交通航、儲水及供水需求矩陣。","checkEn":"Provide a navigation, storage and water-supply requirements matrix.","knowledge":[{"id":"b226-v7-06-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"工程容量與自然資源供給屬不同約束，兩者需在同一系統範圍下協調。","textEn":"Engineering capacity and natural supply are different constraints requiring coordination within one system boundary."},{"id":"b226-v7-06-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本課程不推定當前水位、通航限額或政策；這些需查最新營運公告。","textEn":"The course does not infer current levels, transit limits or policy, which require current operator notices."}],"quiz":{"question":"審查「審查通航與水資源需求」時，哪個判讀有根據？","questionEn":"When reviewing “Review navigation and water-resource needs”, which interpretation is justified?","options":["增加閘室尺寸會自動增加流域可用水量。","自然降雨與工程容量是可以互相替代的相同約束。","更大的船閘不能單獨保證任何乾旱條件下都有足夠淡水。"],"optionsEn":["Increasing chamber size automatically increases available watershed water.","Natural rainfall and engineering capacity are interchangeable constraints.","Larger locks alone cannot guarantee sufficient freshwater under every drought condition."],"answer":2,"explanation":"工程容量與自然資源供給屬不同約束，兩者需在同一系統範圍下協調。 本課程不推定當前水位、通航限額或政策；這些需查最新營運公告。","explanationEn":"Engineering capacity and natural supply are different constraints requiring coordination within one system boundary. The course does not infer current levels, transit limits or policy, which require current operator notices."}}]},{"id":"b226-stage02","order":2,"title":"閘室土建與大型閘門","titleEn":"Lock civil works and large gates","description":"以六個相互銜接的練習完成「閘室土建與大型閘門」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on lock civil works and large gates, retaining assumptions, diagrams and evidence.","steps":[{"id":"b226-v7-07","sequence":7,"order":1,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-06"],"title":"拆出開挖、地盤與閘室底板","titleEn":"Separate excavation, ground and lock floor","objective":"辨識擋土、地下水與承載的不同問題。","objectiveEn":"Distinguish retaining, groundwater and bearing questions.","instruction":"1. 畫概念基坑與閘室底板；2. 標出土水壓與結構自重方向；3. 分別列出地盤、地下水及結構證據需求。","instructionEn":"1. Draw a conceptual excavation and lock floor; 2. mark earth, water and self-weight directions; 3. list ground, groundwater and structural evidence separately.","observation":"水位改變會影響地下結構受力，不能只考慮上部船閘重量。","observationEn":"Water-level changes affect underground structural actions beyond the weight of the lock.","failure":"底板很厚就可以忽略地下水及地盤變形。","failureEn":"A thick floor slab makes groundwater and ground deformation irrelevant.","check":"提交一張含水壓及地盤反力的概念剖面。","checkEn":"Submit a conceptual section with water pressure and ground reactions.","knowledge":[{"id":"b226-v7-07-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"基坑與完工閘室具有不同水位及支承狀態，應分開建模。","textEn":"Excavations and completed locks have different water levels and supports and require separate models."},{"id":"b226-v7-07-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本步不提供降水、支撐或開挖方案，而是列出必須具備的設計證據。","textEn":"This step supplies no dewatering, support or excavation scheme; it identifies necessary design evidence."}],"quiz":{"question":"審查「拆出開挖、地盤與閘室底板」時，哪個判讀有根據？","questionEn":"When reviewing “Separate excavation, ground and lock floor”, which interpretation is justified?","options":["水位改變會影響地下結構受力，不能只考慮上部船閘重量。","底板很厚就可以忽略地下水及地盤變形。","基坑與完工閘室可以假定永遠具有同一水位與支承。"],"optionsEn":["Water-level changes affect underground structural actions beyond the weight of the lock.","A thick floor slab makes groundwater and ground deformation irrelevant.","Excavations and completed locks can always share identical levels and support conditions."],"answer":0,"explanation":"基坑與完工閘室具有不同水位及支承狀態，應分開建模。 本步不提供降水、支撐或開挖方案，而是列出必須具備的設計證據。","explanationEn":"Excavations and completed locks have different water levels and supports and require separate models. This step supplies no dewatering, support or excavation scheme; it identifies necessary design evidence."}},{"id":"b226-v7-08","sequence":8,"order":2,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-07"],"title":"理解大體積混凝土的溫度歷程","titleEn":"Understand mass-concrete temperature history","objective":"將材料強度與溫度變形分開。","objectiveEn":"Separate material strength from thermal deformation.","instruction":"1. 畫一塊概念厚牆的中心與表面；2. 自設兩條溫度曲線；3. 比較溫差、約束與裂縫風險之間的關係。","instructionEn":"1. Draw the core and surface of a conceptual thick wall; 2. create two temperature histories; 3. relate temperature difference, restraint and cracking risk.","observation":"強度資料合格不會自動消除受約束溫度變形的問題。","observationEn":"Acceptable strength data do not automatically eliminate restrained thermal-deformation issues.","failure":"混凝土越厚就一定越不需考慮內外溫差。","failureEn":"Thicker concrete necessarily needs less consideration of internal temperature differences.","check":"輸出溫度歷程與約束位置的配對圖。","checkEn":"Provide paired temperature histories and restraint locations.","knowledge":[{"id":"b226-v7-08-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"水化產熱、散熱及約束會共同影響溫度應力，不能只看單點最高溫。","textEn":"Hydration heat, cooling and restraint jointly influence thermal stress, beyond one peak temperature."},{"id":"b226-v7-08-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"課程的溫度曲線是教學自設，不提供實際混凝土配比或養護設定。","textEn":"Teaching temperature curves provide no actual mix design or curing settings."}],"quiz":{"question":"審查「理解大體積混凝土的溫度歷程」時，哪個判讀有根據？","questionEn":"When reviewing “Understand mass-concrete temperature history”, which interpretation is justified?","options":["混凝土越厚就一定越不需考慮內外溫差。","強度資料合格不會自動消除受約束溫度變形的問題。","只記最高溫度就能完整描述受約束溫度應力。"],"optionsEn":["Thicker concrete necessarily needs less consideration of internal temperature differences.","Acceptable strength data do not automatically eliminate restrained thermal-deformation issues.","One maximum temperature completely describes restrained thermal stress."],"answer":1,"explanation":"水化產熱、散熱及約束會共同影響溫度應力，不能只看單點最高溫。 課程的溫度曲線是教學自設，不提供實際混凝土配比或養護設定。","explanationEn":"Hydration heat, cooling and restraint jointly influence thermal stress, beyond one peak temperature. Teaching temperature curves provide no actual mix design or curing settings."}},{"id":"b226-v7-09","sequence":9,"order":3,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-08"],"title":"核對施工縫與止水介面","titleEn":"Review joints and waterstops","objective":"理解連續防水依賴局部接合品質。","objectiveEn":"Understand how continuous water control depends on local joints.","instruction":"1. 畫底板、牆及一條概念施工縫；2. 標出水的可能穿越路徑；3. 建立位置、材料及隱蔽檢查的追溯表。","instructionEn":"1. Draw floor, wall and a conceptual construction joint; 2. mark possible water crossings; 3. create a location, material and concealed-inspection record.","observation":"大面積混凝土完整不等於每一條接縫都已驗證水密。","observationEn":"Intact bulk concrete does not establish watertightness at every joint.","failure":"表面無裂痕就能證明所有隱蔽止水構件正確安裝。","failureEn":"A crack-free surface proves correct installation of all concealed waterstops.","check":"提交至少三類接縫證據與各自限制。","checkEn":"Provide at least three joint-evidence types with their limitations.","knowledge":[{"id":"b226-v7-09-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"防水介面是連續路徑問題，局部缺口可能主導整體滲漏。","textEn":"Water control is a continuity problem in which a local gap can dominate leakage."},{"id":"b226-v7-09-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"照片可協助追溯位置，但材料識別與施工紀錄仍需各自保留。","textEn":"Photos help trace locations, while material identification and installation records remain separate needs."}],"quiz":{"question":"審查「核對施工縫與止水介面」時，哪個判讀有根據？","questionEn":"When reviewing “Review joints and waterstops”, which interpretation is justified?","options":["表面無裂痕就能證明所有隱蔽止水構件正確安裝。","隱蔽止水細節能由完工外觀唯一推定。","大面積混凝土完整不等於每一條接縫都已驗證水密。"],"optionsEn":["A crack-free surface proves correct installation of all concealed waterstops.","Concealed waterstop details can be uniquely inferred from finished appearance.","Intact bulk concrete does not establish watertightness at every joint."],"answer":2,"explanation":"防水介面是連續路徑問題，局部缺口可能主導整體滲漏。 照片可協助追溯位置，但材料識別與施工紀錄仍需各自保留。","explanationEn":"Water control is a continuity problem in which a local gap can dominate leakage. Photos help trace locations, while material identification and installation records remain separate needs."}},{"id":"b226-v7-10","sequence":10,"order":4,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-09"],"title":"辨認滾動閘門的空間包絡","titleEn":"Identify rolling-gate movement envelopes","objective":"區分閘門封水、移動及檢修空間。","objectiveEn":"Distinguish sealing, movement and maintenance spaces.","instruction":"1. 畫閘室與側向閘門凹槽；2. 以虛線標出概念移動包絡；3. 列出結構、驅動及維護三類介面。","instructionEn":"1. Draw a chamber and lateral gate recess; 2. mark a conceptual movement envelope; 3. list structural, drive and maintenance interfaces.","observation":"閘門能放入凹槽不等於移動、密封及維護條件全部成立。","observationEn":"A gate fitting its recess does not establish movement, sealing and maintenance requirements.","failure":"只要閘門外形吻合開口，所有機械介面便可省略。","failureEn":"A gate outline matching the opening makes every mechanical interface unnecessary.","check":"輸出三種空間與介面分色的平面圖。","checkEn":"Produce a plan separating three spaces and interface types by color.","knowledge":[{"id":"b226-v7-10-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"滾動門的側向移動與原運河人字門的旋轉不同，不能沿用相同幾何模型。","textEn":"Rolling-gate translation differs from original miter-gate rotation and needs a different geometric model."},{"id":"b226-v7-10-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本圖不提供運動速度、驅動力或現場維護操作值。","textEn":"The diagram supplies no movement speeds, drive forces or field maintenance settings."}],"quiz":{"question":"審查「辨認滾動閘門的空間包絡」時，哪個判讀有根據？","questionEn":"When reviewing “Identify rolling-gate movement envelopes”, which interpretation is justified?","options":["閘門能放入凹槽不等於移動、密封及維護條件全部成立。","只要閘門外形吻合開口，所有機械介面便可省略。","滾動門的檢修空間可由封水位置的外框直接代替。"],"optionsEn":["A gate fitting its recess does not establish movement, sealing and maintenance requirements.","A gate outline matching the opening makes every mechanical interface unnecessary.","A rolling gate’s closed outline directly substitutes for its maintenance space."],"answer":0,"explanation":"滾動門的側向移動與原運河人字門的旋轉不同，不能沿用相同幾何模型。 本圖不提供運動速度、驅動力或現場維護操作值。","explanationEn":"Rolling-gate translation differs from original miter-gate rotation and needs a different geometric model. The diagram supplies no movement speeds, drive forces or field maintenance settings."}},{"id":"b226-v7-11","sequence":11,"order":5,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-10"],"title":"追溯大型閘門製造與運輸","titleEn":"Trace gate fabrication and transport evidence","objective":"理解製造完成與現地適合安裝的差別。","objectiveEn":"Distinguish fabrication completion from site installation readiness.","instruction":"1. 畫製造、海運、暫存及安裝四個資料節點；2. 每段列出幾何與狀態紀錄；3. 加入到場損傷及版本不符的假想例子。","instructionEn":"1. Draw fabrication, sea transport, storage and installation records; 2. list geometry and condition evidence at each stage; 3. introduce hypothetical arrival damage and revision mismatch.","observation":"出廠驗證不會自動覆蓋運輸及到場後的狀態變化。","observationEn":"Factory verification does not automatically cover transport and post-arrival condition changes.","failure":"供應商出廠合格即可刪除所有到場介面複核。","failureEn":"Supplier factory acceptance eliminates every arrival-interface review.","check":"提交一件構件從出廠到移交的資料鏈。","checkEn":"Provide one component’s evidence chain from factory to handover.","knowledge":[{"id":"b226-v7-11-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"大型構件的品質包含幾何、材料、運輸支承及狀態追溯，不能只看重量。","textEn":"Large-component quality involves geometry, material, transport support and condition traceability, not weight alone."},{"id":"b226-v7-11-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"歷史運輸照片可說明尺度及物流背景，不是可複製的吊運計畫。","textEn":"Historical transport photographs explain scale and logistics context, not a reusable lifting plan."}],"quiz":{"question":"審查「追溯大型閘門製造與運輸」時，哪個判讀有根據？","questionEn":"When reviewing “Trace gate fabrication and transport evidence”, which interpretation is justified?","options":["供應商出廠合格即可刪除所有到場介面複核。","出廠驗證不會自動覆蓋運輸及到場後的狀態變化。","大型構件重量一致就表示運輸後幾何與狀態未改變。"],"optionsEn":["Supplier factory acceptance eliminates every arrival-interface review.","Factory verification does not automatically cover transport and post-arrival condition changes.","Equal component weight proves geometry and condition are unchanged after transport."],"answer":1,"explanation":"大型構件的品質包含幾何、材料、運輸支承及狀態追溯，不能只看重量。 歷史運輸照片可說明尺度及物流背景，不是可複製的吊運計畫。","explanationEn":"Large-component quality involves geometry, material, transport support and condition traceability, not weight alone. Historical transport photographs explain scale and logistics context, not a reusable lifting plan."}},{"id":"b226-v7-12","sequence":12,"order":6,"sourceIds":["v7-panama-expanded","v7-panama-basins","v7-panama-gates"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-11"],"title":"審查閘門—土建的公差鏈","titleEn":"Review gate-to-civil tolerance chains","objective":"把零件尺寸轉成整體介面配合。","objectiveEn":"Translate component dimensions into assembled interface compatibility.","instruction":"1. 自設閘門、凹槽及導向三個尺寸；2. 分別加入同向及反向偏差；3. 比較剩餘間隙並記錄共同基準。","instructionEn":"1. Invent gate, recess and guide dimensions; 2. apply same-direction and opposite-direction deviations; 3. compare remaining clearances under one datum.","observation":"各零件在自有公差內仍可能組成不相容的介面。","observationEn":"Individually in-tolerance parts can still create an incompatible assembly.","failure":"每個供應商都合格就代表組合間隙一定合適。","failureEn":"Every supplier passing guarantees acceptable assembly clearance.","check":"輸出有單位、基準及最不利組合的公差表。","checkEn":"Provide a tolerance table with units, datums and adverse combinations.","knowledge":[{"id":"b226-v7-12-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"配合由多項尺寸共同決定，系統性偏差與不同基準會增加閉合問題。","textEn":"Fit depends on multiple dimensions; systematic bias and inconsistent datums can worsen closure."},{"id":"b226-v7-12-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"自設間隙只用於理解累積，不是實際閘門可接受偏差。","textEn":"Invented clearances explain accumulation and are not permissible real-gate tolerances."}],"quiz":{"question":"審查「審查閘門—土建的公差鏈」時，哪個判讀有根據？","questionEn":"When reviewing “Review gate-to-civil tolerance chains”, which interpretation is justified?","options":["每個供應商都合格就代表組合間隙一定合適。","相同方向的公差一定會互相抵消並增加間隙。","各零件在自有公差內仍可能組成不相容的介面。"],"optionsEn":["Every supplier passing guarantees acceptable assembly clearance.","Same-direction tolerances necessarily cancel and increase clearance.","Individually in-tolerance parts can still create an incompatible assembly."],"answer":2,"explanation":"配合由多項尺寸共同決定，系統性偏差與不同基準會增加閉合問題。 自設間隙只用於理解累積，不是實際閘門可接受偏差。","explanationEn":"Fit depends on multiple dimensions; systematic bias and inconsistent datums can worsen closure. Invented clearances explain accumulation and are not permissible real-gate tolerances."}}]},{"id":"b226-stage03","order":3,"title":"水力與功能介面驗證","titleEn":"Hydraulic and functional interfaces","description":"以六個相互銜接的練習完成「水力與功能介面驗證」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on hydraulic and functional interfaces, retaining assumptions, diagrams and evidence.","steps":[{"id":"b226-v7-13","sequence":13,"order":1,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-12"],"title":"畫出節水池的儲水層級","titleEn":"Draw the water-saving basin levels","objective":"理解多池系統如何提供不同儲水位置。","objectiveEn":"Understand distinct storage levels in a multiple-basin system.","instruction":"1. 畫一個閘室及三個概念節水池；2. 標出水面高程及連通關係；3. 將內部轉移與外部供水箭頭分開。","instructionEn":"1. Draw one chamber and three conceptual saving basins; 2. mark levels and connections; 3. separate internal transfers from external supply.","observation":"節水池回用作用需要水位及連通條件，不能只靠池子的存在。","observationEn":"Basin reuse requires level and connection conditions, not merely the presence of basins.","failure":"新增池子但不核對高程及連通仍能保證相同節水效果。","failureEn":"Adding basins without checking levels and connections guarantees identical savings.","check":"提交有高程基準的池室連通圖。","checkEn":"Submit a basin-chamber connection map with a level datum.","knowledge":[{"id":"b226-v7-13-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"水的可轉移量受幾何與水位差影響，儲水總容量不能直接當成每次回用量。","textEn":"Transferable water depends on geometry and head difference; total storage is not automatically reused per cycle."},{"id":"b226-v7-13-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本步僅建立水力概念，不提供真實節水池閥門時序。","textEn":"This step builds hydraulic concepts and provides no actual basin-valve sequence."}],"quiz":{"question":"審查「畫出節水池的儲水層級」時，哪個判讀有根據？","questionEn":"When reviewing “Draw the water-saving basin levels”, which interpretation is justified?","options":["節水池回用作用需要水位及連通條件，不能只靠池子的存在。","新增池子但不核對高程及連通仍能保證相同節水效果。","節水池總容量就是每個航次必定回用的水量。"],"optionsEn":["Basin reuse requires level and connection conditions, not merely the presence of basins.","Adding basins without checking levels and connections guarantees identical savings.","Total basin capacity equals water necessarily reused on every transit."],"answer":0,"explanation":"水的可轉移量受幾何與水位差影響，儲水總容量不能直接當成每次回用量。 本步僅建立水力概念，不提供真實節水池閥門時序。","explanationEn":"Transferable water depends on geometry and head difference; total storage is not automatically reused per cycle. This step builds hydraulic concepts and provides no actual basin-valve sequence."}},{"id":"b226-v7-14","sequence":14,"order":2,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-13"],"title":"區分靜水壓與流動瞬變","titleEn":"Distinguish hydrostatic and transient effects","objective":"避免用靜止水面推定所有充排水現象。","objectiveEn":"Avoid inferring every filling or emptying effect from still-water levels.","instruction":"1. 畫靜止水面下的壓力趨勢；2. 另畫概念管路流量變化；3. 分列穩態、瞬變及結構反應三種問題。","instructionEn":"1. Sketch pressure trends beneath a still surface; 2. separately sketch changing conduit flow; 3. distinguish steady, transient and structural-response questions.","observation":"相同起訖水位不保證過程中的流量及壓力歷程相同。","observationEn":"Identical initial and final levels do not guarantee identical flow or pressure histories.","failure":"只知道最後水位即可證明整段充水過程沒有瞬變問題。","failureEn":"Knowing the final level proves the filling process has no transient issues.","check":"繳交狀態量與過程量的比較表。","checkEn":"Provide a comparison of state quantities and process quantities.","knowledge":[{"id":"b226-v7-14-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"靜水壓描述近乎靜止條件；改變流速涉及動量及時間效應。","textEn":"Hydrostatic pressure describes near-stationary conditions; changing velocity introduces momentum and time effects."},{"id":"b226-v7-14-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"概念曲線不設定流速、開關速率或設備極限，也不取代水力試驗。","textEn":"Conceptual curves set no velocities, actuation rates or equipment limits and do not replace hydraulic tests."}],"quiz":{"question":"審查「區分靜水壓與流動瞬變」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish hydrostatic and transient effects”, which interpretation is justified?","options":["只知道最後水位即可證明整段充水過程沒有瞬變問題。","相同起訖水位不保證過程中的流量及壓力歷程相同。","靜水壓圖已包含全部流速變化的時間效應。"],"optionsEn":["Knowing the final level proves the filling process has no transient issues.","Identical initial and final levels do not guarantee identical flow or pressure histories.","A hydrostatic-pressure diagram already includes all time effects of changing velocity."],"answer":1,"explanation":"靜水壓描述近乎靜止條件；改變流速涉及動量及時間效應。 概念曲線不設定流速、開關速率或設備極限，也不取代水力試驗。","explanationEn":"Hydrostatic pressure describes near-stationary conditions; changing velocity introduces momentum and time effects. Conceptual curves set no velocities, actuation rates or equipment limits and do not replace hydraulic tests."}},{"id":"b226-v7-15","sequence":15,"order":3,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-14"],"title":"檢查船舶包絡與水位情境","titleEn":"Check vessel envelopes across level cases","objective":"把吃水、浮體及閘室幾何分開。","objectiveEn":"Separate draft, floating-body geometry and chamber dimensions.","instruction":"1. 畫一個假想船體及水線；2. 比較兩個自設水位情境；3. 將船舶尺度與通航核准資料分成不同欄。","instructionEn":"1. Draw a hypothetical hull and waterline; 2. compare two invented level cases; 3. separate vessel dimensions from navigation-approval data.","observation":"船體在示意圖內放得下不代表符合實際通航條件。","observationEn":"A vessel fitting inside a drawing does not establish actual navigation eligibility.","failure":"以滑鼠把船放入閘室就等於完成吃水與通航驗證。","failureEn":"Dragging a ship into a chamber completes draft and navigation verification.","check":"提交幾何假設、情境與未知條件三欄表。","checkEn":"Provide geometric assumptions, scenarios and unknown conditions.","knowledge":[{"id":"b226-v7-15-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"船舶浮態與可用水深具有共同邊界，通航評估還需要營運及船舶資料。","textEn":"Vessel flotation and available depth share boundaries; navigation review also needs operating and vessel information."},{"id":"b226-v7-15-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本模型不提供允許吃水、船寬或實際航行建議。","textEn":"The model provides no permissible draft, beam or actual navigation advice."}],"quiz":{"question":"審查「檢查船舶包絡與水位情境」時，哪個判讀有根據？","questionEn":"When reviewing “Check vessel envelopes across level cases”, which interpretation is justified?","options":["以滑鼠把船放入閘室就等於完成吃水與通航驗證。","閘室土建尺寸可以直接取代營運者的船舶核准條件。","船體在示意圖內放得下不代表符合實際通航條件。"],"optionsEn":["Dragging a ship into a chamber completes draft and navigation verification.","Chamber civil dimensions directly replace operator vessel-approval conditions.","A vessel fitting inside a drawing does not establish actual navigation eligibility."],"answer":2,"explanation":"船舶浮態與可用水深具有共同邊界，通航評估還需要營運及船舶資料。 本模型不提供允許吃水、船寬或實際航行建議。","explanationEn":"Vessel flotation and available depth share boundaries; navigation review also needs operating and vessel information. The model provides no permissible draft, beam or actual navigation advice."}},{"id":"b226-v7-16","sequence":16,"order":4,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-15"],"title":"把水位感測與設備狀態分開","titleEn":"Separate level sensing from equipment state","objective":"理解量測與命令確認的不同證據。","objectiveEn":"Understand separate evidence for measurement and command confirmation.","instruction":"1. 畫水位感測、控制判斷及設備回饋三個節點；2. 用不同箭頭標記資料和命令；3. 加入一個感測器失準的假想案例。","instructionEn":"1. Draw level sensing, control decision and equipment-feedback nodes; 2. distinguish data from commands; 3. introduce a hypothetical sensor bias.","observation":"發出命令與設備達到所需狀態是兩件需分別證實的事。","observationEn":"Issuing a command and reaching the required equipment state need separate evidence.","failure":"控制畫面顯示命令已送出就能證明閘門機械位置正確。","failureEn":"A sent-command display proves the gate’s mechanical position is correct.","check":"提供命令、回饋及獨立查證的功能圖。","checkEn":"Provide a function map of command, feedback and independent verification.","knowledge":[{"id":"b226-v7-16-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"控制系統依靠狀態資訊，感測偏差與回饋缺失需在概念驗證中區分。","textEn":"Controls rely on state information; biased sensing and missing feedback are distinct verification questions."},{"id":"b226-v7-16-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"此圖僅為一般工程原理，不揭示或模擬真實船閘控制邏輯。","textEn":"The diagram teaches general principles and neither reveals nor simulates actual lock-control logic."}],"quiz":{"question":"審查「把水位感測與設備狀態分開」時，哪個判讀有根據？","questionEn":"When reviewing “Separate level sensing from equipment state”, which interpretation is justified?","options":["發出命令與設備達到所需狀態是兩件需分別證實的事。","控制畫面顯示命令已送出就能證明閘門機械位置正確。","水位感測器正常就能證明閘門機械回饋也正常。"],"optionsEn":["Issuing a command and reaching the required equipment state need separate evidence.","A sent-command display proves the gate’s mechanical position is correct.","A functioning level sensor proves correct mechanical gate feedback."],"answer":0,"explanation":"控制系統依靠狀態資訊，感測偏差與回饋缺失需在概念驗證中區分。 此圖僅為一般工程原理，不揭示或模擬真實船閘控制邏輯。","explanationEn":"Controls rely on state information; biased sensing and missing feedback are distinct verification questions. The diagram teaches general principles and neither reveals nor simulates actual lock-control logic."}},{"id":"b226-v7-17","sequence":17,"order":5,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-16"],"title":"建立水密試驗的證據結構","titleEn":"Structure evidence for a watertightness test","objective":"區分試驗結果與試驗覆蓋範圍。","objectiveEn":"Distinguish a test result from its coverage.","instruction":"1. 選一個概念節水池邊界；2. 列出初始狀態、觀察量及資料期間；3. 明確寫下此次測試未涵蓋的介面。","instructionEn":"1. Select a conceptual basin boundary; 2. list initial state, observations and record duration; 3. state interfaces outside this test.","observation":"一次局部水密結果不能直接證明整個閘室系統所有功能。","observationEn":"One local watertightness result does not verify every function of the complete lock system.","failure":"節水池不漏水便表示閘門、控制及通航全部已驗收。","failureEn":"A watertight basin means gates, controls and navigation are fully accepted.","check":"輸出含邊界與不適用範圍的試驗摘要範本。","checkEn":"Provide a test-summary template with boundaries and exclusions.","knowledge":[{"id":"b226-v7-17-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"試驗論證需描述狀態、量測及判定依據；只有通過二字不足以追溯。","textEn":"A test argument needs state, observations and judgment basis; a bare pass label is not traceable."},{"id":"b226-v7-17-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"官方試水新聞提供建設里程碑，課程不由新聞反推實際驗收限值。","textEn":"Official filling-test news provides a milestone; this course does not infer acceptance limits from it."}],"quiz":{"question":"審查「建立水密試驗的證據結構」時，哪個判讀有根據？","questionEn":"When reviewing “Structure evidence for a watertightness test”, which interpretation is justified?","options":["節水池不漏水便表示閘門、控制及通航全部已驗收。","一次局部水密結果不能直接證明整個閘室系統所有功能。","試驗只需保留通過標記，不需保留當時邊界。"],"optionsEn":["A watertight basin means gates, controls and navigation are fully accepted.","One local watertightness result does not verify every function of the complete lock system.","Testing needs only a pass label and no record of boundaries."],"answer":1,"explanation":"試驗論證需描述狀態、量測及判定依據；只有通過二字不足以追溯。 官方試水新聞提供建設里程碑，課程不由新聞反推實際驗收限值。","explanationEn":"A test argument needs state, observations and judgment basis; a bare pass label is not traceable. Official filling-test news provides a milestone; this course does not infer acceptance limits from it."}},{"id":"b226-v7-18","sequence":18,"order":6,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-17"],"title":"做跨專業整合審查","titleEn":"Review multidisciplinary integration","objective":"讓土建、水力、機械與控制使用同一套邊界。","objectiveEn":"Align boundaries across civil, hydraulic, mechanical and control disciplines.","instruction":"1. 把四類系統放進介面矩陣；2. 每對介面填入共享量與版本；3. 追查一個水位基準變更的全部影響。","instructionEn":"1. Place four system classes in an interface matrix; 2. record shared quantities and versions; 3. trace all effects of one level-datum change.","observation":"共享水位基準不一致可能讓各自正確的子系統產生整體衝突。","observationEn":"Inconsistent shared level datums can make individually correct subsystems incompatible.","failure":"每一專業自己的圖面通過就保證交界完全一致。","failureEn":"Every discipline’s drawing approval guarantees compatible interfaces.","check":"提交一份含跨專業問題及修訂欄的矩陣。","checkEn":"Submit a matrix with multidisciplinary issues and revision fields.","knowledge":[{"id":"b226-v7-18-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"大型水工工程的錯誤常落在介面與資料定義，需明確協調責任與版本。","textEn":"Large hydraulic works need explicit responsibility and version control at interfaces and data definitions."},{"id":"b226-v7-18-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"介面審查不是實際系統投運許可；後者還需正式程序與專業驗證。","textEn":"Interface review is not permission to commission a real system, which requires formal procedures and professional verification."}],"quiz":{"question":"審查「做跨專業整合審查」時，哪個判讀有根據？","questionEn":"When reviewing “Review multidisciplinary integration”, which interpretation is justified?","options":["每一專業自己的圖面通過就保證交界完全一致。","土建與控制採用不同水位零點不會影響結果。","共享水位基準不一致可能讓各自正確的子系統產生整體衝突。"],"optionsEn":["Every discipline’s drawing approval guarantees compatible interfaces.","Different level zero points in civil and control systems cannot affect results.","Inconsistent shared level datums can make individually correct subsystems incompatible."],"answer":2,"explanation":"大型水工工程的錯誤常落在介面與資料定義，需明確協調責任與版本。 介面審查不是實際系統投運許可；後者還需正式程序與專業驗證。","explanationEn":"Large hydraulic works need explicit responsibility and version control at interfaces and data definitions. Interface review is not permission to commission a real system, which requires formal procedures and professional verification."}}]},{"id":"b226-stage04","order":4,"title":"維護、流域與衍生工程","titleEn":"Maintenance, watershed and related works","description":"以六個相互銜接的練習完成「維護、流域與衍生工程」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on maintenance, watershed and related works, retaining assumptions, diagrams and evidence.","steps":[{"id":"b226-v7-19","sequence":19,"order":1,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-18"],"title":"辨識密封劣化與量測誤差","titleEn":"Distinguish seal degradation and observation errors","objective":"避免從單一滲漏數字推定唯一故障。","objectiveEn":"Avoid inferring a unique fault from one leakage value.","instruction":"1. 自設三段水位與流量紀錄；2. 分別加入密封變化、量測偏移及水位差變化；3. 找出需要獨立查證的訊號。","instructionEn":"1. Create three level and flow records; 2. introduce seal changes, sensor offsets and changed head; 3. identify signals needing independent confirmation.","observation":"流量增加可能來自水位差或量測改變，不一定只有密封劣化。","observationEn":"Higher flow can reflect changed head or measurements, not only seal degradation.","failure":"只要漏水數字上升就能確定是哪一段密封失效。","failureEn":"An increased leakage number uniquely identifies the failed seal segment.","check":"輸出至少三種原因的辨識表。","checkEn":"Produce a discrimination table for at least three causes.","knowledge":[{"id":"b226-v7-19-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"診斷需要把驅動條件與設備狀態一起比較，不能只看輸出數字。","textEn":"Diagnosis compares driving conditions with equipment state rather than output numbers alone."},{"id":"b226-v7-19-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"自設紀錄用於練習排除混淆因素，不代表任一真實閘門有缺陷。","textEn":"Synthetic records practice separating confounders and imply no defect in any real gate."}],"quiz":{"question":"審查「辨識密封劣化與量測誤差」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish seal degradation and observation errors”, which interpretation is justified?","options":["流量增加可能來自水位差或量測改變，不一定只有密封劣化。","只要漏水數字上升就能確定是哪一段密封失效。","水位差改變不可能影響量到的漏水流量。"],"optionsEn":["Higher flow can reflect changed head or measurements, not only seal degradation.","An increased leakage number uniquely identifies the failed seal segment.","Changed water head cannot affect observed leakage flow."],"answer":0,"explanation":"診斷需要把驅動條件與設備狀態一起比較，不能只看輸出數字。 自設紀錄用於練習排除混淆因素，不代表任一真實閘門有缺陷。","explanationEn":"Diagnosis compares driving conditions with equipment state rather than output numbers alone. Synthetic records practice separating confounders and imply no defect in any real gate."}},{"id":"b226-v7-20","sequence":20,"order":2,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-19"],"title":"建立維護可達性與備援觀點","titleEn":"Review maintenance access and redundancy","objective":"理解能維修與仍有服務能力是不同問題。","objectiveEn":"Understand that maintainability and retained service are separate questions.","instruction":"1. 在概念系統標出待維護設備；2. 列出接近、隔離及其他路徑的證據需求；3. 分开局部備援與共同依賴。","instructionEn":"1. Mark equipment for hypothetical maintenance; 2. list evidence needs for access, separation and alternate paths; 3. distinguish local redundancy from shared dependencies.","observation":"兩套設備若共用同一個關鍵依賴，不代表完全獨立備援。","observationEn":"Two equipment sets sharing a critical dependency are not fully independent redundancy.","failure":"設備數量加倍便可忽略共同供電或共同土建介面。","failureEn":"Doubling equipment count makes shared power or civil interfaces irrelevant.","check":"繳交備援、共同原因與待查資料表。","checkEn":"Provide a table of redundancy, common causes and evidence gaps.","knowledge":[{"id":"b226-v7-20-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"可靠性要看功能路徑及共同失效因素，而非只數設備件數。","textEn":"Reliability depends on functional paths and common-cause factors, not equipment count alone."},{"id":"b226-v7-20-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本步不提供隔離、檢修或現場替代操作方法，只建立審查問題。","textEn":"This step provides no isolation, servicing or substitute operating method; it defines review questions."}],"quiz":{"question":"審查「建立維護可達性與備援觀點」時，哪個判讀有根據？","questionEn":"When reviewing “Review maintenance access and redundancy”, which interpretation is justified?","options":["設備數量加倍便可忽略共同供電或共同土建介面。","兩套設備若共用同一個關鍵依賴，不代表完全獨立備援。","兩個設備共用同一依賴仍必定構成完全獨立備援。"],"optionsEn":["Doubling equipment count makes shared power or civil interfaces irrelevant.","Two equipment sets sharing a critical dependency are not fully independent redundancy.","Two devices sharing one dependency necessarily form fully independent redundancy."],"answer":1,"explanation":"可靠性要看功能路徑及共同失效因素，而非只數設備件數。 本步不提供隔離、檢修或現場替代操作方法，只建立審查問題。","explanationEn":"Reliability depends on functional paths and common-cause factors, not equipment count alone. This step provides no isolation, servicing or substitute operating method; it defines review questions."}},{"id":"b226-v7-21","sequence":21,"order":3,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-20"],"title":"把航次與流域資料分層","titleEn":"Separate transit and watershed records","objective":"連結局部節水與長期水資源帳。","objectiveEn":"Connect local reuse with long-term water-resource accounting.","instruction":"1. 建立一次概念航次水帳；2. 另建月尺度入流、蒸發與取水帳；3. 標記兩者可比較與不可直接相加的量。","instructionEn":"1. Create a conceptual transit water ledger; 2. create a monthly inflow, evaporation and withdrawal ledger; 3. mark comparable and nonadditive quantities.","observation":"單次回用表現不能單獨代表整個流域的長期供需平衡。","observationEn":"Per-transit reuse alone does not establish long-term watershed balance.","failure":"一個航次節水就能推出整個月水庫蓄水必然增加。","failureEn":"Water saving on one transit proves reservoir storage must rise over the month.","check":"提交兩個時間尺度的守恆表與連結項。","checkEn":"Provide balances at two time scales with their connecting terms.","knowledge":[{"id":"b226-v7-21-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"水資源分析的時間與空間邊界必須一致；不同尺度的指標不能直接混算。","textEn":"Water-resource analysis needs consistent temporal and spatial boundaries; metrics at different scales cannot be mixed directly."},{"id":"b226-v7-21-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"長期判讀需資料完整性與不確定性，不由單次示範動畫推論。","textEn":"Long-term interpretation requires complete records and uncertainty treatment, not one demonstration animation."}],"quiz":{"question":"審查「把航次與流域資料分層」時，哪個判讀有根據？","questionEn":"When reviewing “Separate transit and watershed records”, which interpretation is justified?","options":["一個航次節水就能推出整個月水庫蓄水必然增加。","月尺度入流可以直接加到單次航次回用百分比。","單次回用表現不能單獨代表整個流域的長期供需平衡。"],"optionsEn":["Water saving on one transit proves reservoir storage must rise over the month.","Monthly inflow can be added directly to a per-transit reuse percentage.","Per-transit reuse alone does not establish long-term watershed balance."],"answer":2,"explanation":"水資源分析的時間與空間邊界必須一致；不同尺度的指標不能直接混算。 長期判讀需資料完整性與不確定性，不由單次示範動畫推論。","explanationEn":"Water-resource analysis needs consistent temporal and spatial boundaries; metrics at different scales cannot be mixed directly. Long-term interpretation requires complete records and uncertainty treatment, not one demonstration animation."}},{"id":"b226-v7-22","sequence":22,"order":4,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-21"],"title":"比較原運河與其他升船工程","titleEn":"Compare the original canal and other ship-lifting works","objective":"找出相近目的下不同水力與機械解法。","objectiveEn":"Identify different hydraulic and mechanical solutions to related aims.","instruction":"1. 比較原巴拿馬船閘與擴建新閘；2. 再選三峽船閘或升船機查證；3. 分開水位調節、機械升降及資源需求。","instructionEn":"1. Compare original and expanded Panama locks; 2. select Three Gorges locks or its ship lift for further evidence; 3. separate level adjustment, mechanical lifting and resource needs.","observation":"都能升降船舶的工程仍可能有完全不同的承載與能源路徑。","observationEn":"Works that all raise vessels can have very different load and energy paths.","failure":"所有升船設施都可用相同閘門及節水池模型表示。","failureEn":"Every ship-lifting facility can use the same gate and basin model.","check":"繳交三個相似需求與三個不同機理。","checkEn":"Provide three shared needs and three different mechanisms.","knowledge":[{"id":"b226-v7-22-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"衍生學習應比較要解決的問題，再查證各工程使用的具體方案。","textEn":"Related learning compares the problem first, then verifies the particular solution used by each project."},{"id":"b226-v7-22-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"原運河歷史是比較背景，不能把早期設備敘述當成擴建新閘的現況。","textEn":"Original-canal history provides comparison and must not be presented as current expanded-lock equipment."}],"quiz":{"question":"審查「比較原運河與其他升船工程」時，哪個判讀有根據？","questionEn":"When reviewing “Compare the original canal and other ship-lifting works”, which interpretation is justified?","options":["都能升降船舶的工程仍可能有完全不同的承載與能源路徑。","所有升船設施都可用相同閘門及節水池模型表示。","機械升船與調整閘室水位具有完全相同的能源路徑。"],"optionsEn":["Works that all raise vessels can have very different load and energy paths.","Every ship-lifting facility can use the same gate and basin model.","Mechanical vessel lifting and chamber-level adjustment have identical energy paths."],"answer":0,"explanation":"衍生學習應比較要解決的問題，再查證各工程使用的具體方案。 原運河歷史是比較背景，不能把早期設備敘述當成擴建新閘的現況。","explanationEn":"Related learning compares the problem first, then verifies the particular solution used by each project. Original-canal history provides comparison and must not be presented as current expanded-lock equipment."}},{"id":"b226-v7-23","sequence":23,"order":5,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-22"],"title":"查核節水與容量宣稱","titleEn":"Audit water-saving and capacity claims","objective":"把宣傳數字轉成可核對的工程敘述。","objectiveEn":"Turn headline numbers into checkable engineering statements.","instruction":"1. 選一個官方容量或節水敘述；2. 摘出日期、比較對象與條件；3. 改寫成保留限制與未知的學習筆記。","instructionEn":"1. Select an official capacity or saving statement; 2. extract date, comparison basis and conditions; 3. rewrite it as a note retaining limits and unknowns.","observation":"有來源的數字仍需保留日期與適用條件才不會被誤用。","observationEn":"A sourced number still needs its date and applicability conditions to avoid misuse.","failure":"數字來自官方頁面就能不加條件套用到任何年份和航次。","failureEn":"An official number applies unconditionally to every year and transit.","check":"提交一條原意不變且明示範圍的摘要。","checkEn":"Submit one faithful summary with explicit scope.","knowledge":[{"id":"b226-v7-23-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"資料可信與適用於當前問題是兩個不同檢查；來源權威不能取代邊界核對。","textEn":"Credibility and applicability are separate checks; source authority does not replace boundary review."},{"id":"b226-v7-23-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"使用者自設模擬結果不能偽裝成營運者的實際效率或性能保證。","textEn":"User-generated simulation results must not masquerade as operator efficiency data or performance guarantees."}],"quiz":{"question":"審查「查核節水與容量宣稱」時，哪個判讀有根據？","questionEn":"When reviewing “Audit water-saving and capacity claims”, which interpretation is justified?","options":["數字來自官方頁面就能不加條件套用到任何年份和航次。","有來源的數字仍需保留日期與適用條件才不會被誤用。","資料的發布日期與比較基準不影響工程宣稱的適用性。"],"optionsEn":["An official number applies unconditionally to every year and transit.","A sourced number still needs its date and applicability conditions to avoid misuse.","Publication date and comparison basis do not affect a claim’s applicability."],"answer":1,"explanation":"資料可信與適用於當前問題是兩個不同檢查；來源權威不能取代邊界核對。 使用者自設模擬結果不能偽裝成營運者的實際效率或性能保證。","explanationEn":"Credibility and applicability are separate checks; source authority does not replace boundary review. User-generated simulation results must not masquerade as operator efficiency data or performance guarantees."}},{"id":"b226-v7-24","sequence":24,"order":6,"sourceIds":["v7-panama-basins","v7-panama-gates","v7-panama-original","v7-panama-visitor"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b226-v7-23"],"title":"完成水工系統交付報告","titleEn":"Complete the hydraulic-system learning report","objective":"讓幾何、水量、設備與資料保持一致。","objectiveEn":"Align geometry, water balance, equipment and evidence.","instruction":"1. 彙整四階段模型及矩陣；2. 逐一連結來源、假設與未解項；3. 選一個介面變更演練資料更新的傳播。","instructionEn":"1. Assemble four-stage models and matrices; 2. link sources, assumptions and open items; 3. rehearse propagation of one interface revision.","observation":"可複查報告會清楚指出自設模型與真實工程證據的分界。","observationEn":"An auditable report clearly separates invented models from real-project evidence.","failure":"完成全部動畫就可宣稱已掌握真實船閘的投運與操控。","failureEn":"Completing all animations establishes mastery of real lock commissioning and control.","check":"提交含版本、圖例、來源與待查問題的學習檔。","checkEn":"Submit a learning dossier with versions, legends, sources and open questions.","knowledge":[{"id":"b226-v7-24-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"水工巨作需要土建、機械、水力、控制及流域共同成立，局部示範不等於整體驗證。","textEn":"Major hydraulic works depend on civil, mechanical, hydraulic, control and watershed systems together; a local demo is not system verification."},{"id":"b226-v7-24-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本課程交付的是工程概念與證據組織能力，不是現場建造或操作資格。","textEn":"The deliverable is engineering understanding and evidence organization, not field construction or operating qualification."}],"quiz":{"question":"審查「完成水工系統交付報告」時，哪個判讀有根據？","questionEn":"When reviewing “Complete the hydraulic-system learning report”, which interpretation is justified?","options":["完成全部動畫就可宣稱已掌握真實船閘的投運與操控。","每個局部功能動畫成功就等同整體正式驗收完成。","可複查報告會清楚指出自設模型與真實工程證據的分界。"],"optionsEn":["Completing all animations establishes mastery of real lock commissioning and control.","Successful local animations equal completion of formal system acceptance.","An auditable report clearly separates invented models from real-project evidence."],"answer":2,"explanation":"水工巨作需要土建、機械、水力、控制及流域共同成立，局部示範不等於整體驗證。 本課程交付的是工程概念與證據組織能力，不是現場建造或操作資格。","explanationEn":"Major hydraulic works depend on civil, mechanical, hydraulic, control and watershed systems together; a local demo is not system verification. The deliverable is engineering understanding and evidence organization, not field construction or operating qualification."}}]},{"id":"b226-v15-s1","title":"水文條件、邊界與工程系統","titleEn":"Hydrology, boundaries and engineering system","description":"本階段聚焦「雙池水位均衡」與「充水歷線與慣性」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Equalization between two pools\" and \"Filling hydrograph and inertia\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b226-v15-01","title":"雙池水位均衡：機制與系統路徑","titleEn":"Equalization between two pools: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v7-24"],"objective":"說明「雙池水位均衡」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Equalization between two pools” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"兩個有限面積水體連通時，兩邊水位都會改變，不能把節水池當無限水源。守恆終點只由初始體積與面積決定，達到終點的時間則另受管路控制。 假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。 把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。若兩水位計基準不同，甚至會虛構無法解釋的水量損失。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「雙池水位均衡」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Connecting two finite pools changes both levels, so a saving basin is not an infinite reservoir. Conservation determines the equilibrium endpoint from initial storage and areas, while conduits separately determine how quickly it is approached. Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas. Equalized level is (20000×10+10000×4)/30000=8 m. Treating the smaller basin as fixed head overstates recoverable water. Conduit storage, leakage and mismatched gauge datums can also break the apparent balance and create fictitious unexplained water losses. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Equalization between two pools” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas.","failure":"常見誤解：「節水池即使面積有限，交換水量時水位仍保持不變。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A finite saving basin maintains constant level while exchanging water.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「雙池水位均衡」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Equalization between two pools”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-01-k1","title":"雙池水位均衡","titleEn":"Equalization between two pools","text":"兩個有限面積水體連通時，兩邊水位都會改變，不能把節水池當無限水源。守恆終點只由初始體積與面積決定，達到終點的時間則另受管路控制。","textEn":"Connecting two finite pools changes both levels, so a saving basin is not an infinite reservoir. Conservation determines the equilibrium endpoint from initial storage and areas, while conduits separately determine how quickly it is approached.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：節水池即使面積有限，交換水量時水位仍保持不變。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A finite saving basin maintains constant level while exchanging water. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「雙池水位均衡」，下列哪一項敘述正確？","questionEn":"Which statement about \"Equalization between two pools\" is correct?","options":["節水池即使面積有限，交換水量時水位仍保持不變。","兩個有限面積水體連通時，兩邊水位都會改變，不能把節水池當無限水源。","充水量和總時間相同就表示所有瞬時水力荷載相同。"],"optionsEn":["A finite saving basin maintains constant level while exchanging water.","Connecting two finite pools changes both levels, so a saving basin is not an infinite reservoir.","Equal filling volume and total duration imply identical transient hydraulic loads."],"answer":1,"explanation":"兩個有限面積水體連通時，兩邊水位都會改變，不能把節水池當無限水源。 其餘選項是常見誤解。","explanationEn":"Connecting two finite pools changes both levels, so a saving basin is not an infinite reservoir. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b226-v15-02","title":"雙池水位均衡：定量估算","titleEn":"Equalization between two pools: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-01"],"objective":"以數值模型估算「雙池水位均衡」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Equalization between two pools” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas. Equalized level is (20000×10+10000×4)/30000=8 m. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。","observationEn":"How to cross-check: Integrate area times level change on each side and check equal opposite exchange volumes.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas. Equalized level is (20000×10+10000×4)/30000=8 m.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「雙池水位均衡」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Equalization between two pools\", which statement holds?","options":["兩側水面相同時，不同密度水體就不會互相交換。","慢速改變流量也必須產生完整的快速水錘壓峰。","教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定。"],"optionsEn":["Different-density waters stop exchanging when their surface elevations are equal.","A slow flow change must generate the full rapid-waterhammer pressure peak.","Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas."],"answer":2,"explanation":"教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":26},{"id":"b226-v15-03","title":"雙池水位均衡：試驗與驗證","titleEn":"Equalization between two pools: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「雙池水位均衡」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Equalization between two pools” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。另算閘室下降水量與池體上升水量，核對共同終點能同時滿足兩個控制體的守恆。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Integrate area times level change on each side and check equal opposite exchange volumes. Use valve and flow histories to diagnose slowing near equilibrium instead of comparing endpoints alone. Separately calculate chamber loss and basin gain and verify that the shared endpoint closes both control-volume balances. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以雙池水位均衡編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。","observationEn":"Site practice: Prepare a reviewable evidence sheet for equalization between two pools, recording data time, units, model applicability and reviewer. Integrate area times level change on each side and check equal opposite exchange volumes. Use valve and flow histories to diagnose slowing near equilibrium instead of comparing endpoints alone.","failure":"注意干擾：把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Treating the smaller basin as fixed head overstates recoverable water. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-03-k1","title":"驗證方法","titleEn":"Verification method","text":"各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。另算閘室下降水量與池體上升水量，核對共同終點能同時滿足兩個控制體的守恆。","textEn":"Integrate area times level change on each side and check equal opposite exchange volumes. Use valve and flow histories to diagnose slowing near equilibrium instead of comparing endpoints alone. Separately calculate chamber loss and basin gain and verify that the shared endpoint closes both control-volume balances.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-03-k2","title":"現場實務","titleEn":"Site practice","text":"以雙池水位均衡編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。","textEn":"Prepare a reviewable evidence sheet for equalization between two pools, recording data time, units, model applicability and reviewer. Integrate area times level change on each side and check equal opposite exchange volumes. Use valve and flow histories to diagnose slowing near equilibrium instead of comparing endpoints alone.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「雙池水位均衡」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Equalization between two pools\"?","options":["各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","平均水深足夠就能保證整條船底通道都有足夠淨空。"],"optionsEn":["Integrate area times level change on each side and check equal opposite exchange volumes.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Adequate mean depth guarantees clearance along the entire hull route."],"answer":0,"explanation":"各自積分水位變化乘面積，檢查兩側交換體積是否相反相等；再用閥位和流量時序辨識接近均衡時變慢的原因，不能只比較終點。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Integrate area times level change on each side and check equal opposite exchange volumes. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":27},{"id":"b226-v15-04","title":"雙池水位均衡：失效診斷","titleEn":"Equalization between two pools: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-03"],"objective":"從症狀倒推「雙池水位均衡」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Equalization between two pools” and propose discriminating checks, corrective actions and prevention.","instruction":"把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。若兩水位計基準不同，甚至會虛構無法解釋的水量損失。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Treating the smaller basin as fixed head overstates recoverable water. Conduit storage, leakage and mismatched gauge datums can also break the apparent balance and create fictitious unexplained water losses. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：若兩水位計基準不同，甚至會虛構無法解釋的水量損失。","observationEn":"Link to the mechanism: Conduit storage, leakage and mismatched gauge datums can also break the apparent balance and create fictitious unexplained water losses.","failure":"誤判風險：若相信「節水池即使面積有限，交換水量時水位仍保持不變。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A finite saving basin maintains constant level while exchanging water.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-04-k1","title":"失效模式","titleEn":"Failure mode","text":"把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。若兩水位計基準不同，甚至會虛構無法解釋的水量損失。","textEn":"Treating the smaller basin as fixed head overstates recoverable water. Conduit storage, leakage and mismatched gauge datums can also break the apparent balance and create fictitious unexplained water losses.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「雙池水位均衡」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Equalization between two pools\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。","充水量和總時間相同就表示所有瞬時水力荷載相同。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Treating the smaller basin as fixed head overstates recoverable water.","Equal filling volume and total duration imply identical transient hydraulic loads."],"answer":1,"explanation":"把較小池當固定水頭會高估可回用水量，忽略連通管容積和漏流也會破壞守恆。 需以量測區分可能原因。","explanationEn":"Treating the smaller basin as fixed head overstates recoverable water. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":28},{"id":"b226-v15-05","title":"充水歷線與慣性：機制與系統路徑","titleEn":"Filling hydrograph and inertia: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-04"],"objective":"說明「充水歷線與慣性」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Filling hydrograph and inertia” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"船閘水位上升速度取決於當時淨流量，初期加速和末期減速產生的水面坡度又影響船舶受力。平均充水時間無法表示瞬時最大流量。 假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。 同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。若僅用完成時間驗收，可能漏掉局部流速、壓力振盪和繫纜張力峰值。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「充水歷線與慣性」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Lock level rises with instantaneous net flow. Early acceleration and late deceleration also create surface slopes affecting vessels, so average filling time cannot represent peak discharge. Assume triangular filling hydrograph with peak 300 m³/s over 1200 s. Volume is 180000 m³ and rise over 22500 m² is 8 m, not a site operating hydrograph. Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads. Completion time alone misses local velocities, pressure oscillations and maximum mooring tensions during the filling cycle. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Filling hydrograph and inertia” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s.","failure":"常見誤解：「充水量和總時間相同就表示所有瞬時水力荷載相同。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal filling volume and total duration imply identical transient hydraulic loads.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「充水歷線與慣性」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Filling hydrograph and inertia”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-05-k1","title":"充水歷線與慣性","titleEn":"Filling hydrograph and inertia","text":"船閘水位上升速度取決於當時淨流量，初期加速和末期減速產生的水面坡度又影響船舶受力。平均充水時間無法表示瞬時最大流量。","textEn":"Lock level rises with instantaneous net flow. Early acceleration and late deceleration also create surface slopes affecting vessels, so average filling time cannot represent peak discharge.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：充水量和總時間相同就表示所有瞬時水力荷載相同。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal filling volume and total duration imply identical transient hydraulic loads. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「充水歷線與慣性」，下列哪一項敘述正確？","questionEn":"Which statement about \"Filling hydrograph and inertia\" is correct?","options":["充水量和總時間相同就表示所有瞬時水力荷載相同。","閘室平均水位平穩就表示船首船尾沒有壓力差。","船閘水位上升速度取決於當時淨流量，初期加速和末期減速產生的水面坡度又影響船舶受力。"],"optionsEn":["Equal filling volume and total duration imply identical transient hydraulic loads.","A steady mean chamber level means there is no bow-to-stern pressure difference.","Lock level rises with instantaneous net flow."],"answer":2,"explanation":"船閘水位上升速度取決於當時淨流量，初期加速和末期減速產生的水面坡度又影響船舶受力。 其餘選項是常見誤解。","explanationEn":"Lock level rises with instantaneous net flow. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b226-v15-06","title":"充水歷線與慣性：定量估算","titleEn":"Filling hydrograph and inertia: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-05"],"objective":"以數值模型估算「充水歷線與慣性」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Filling hydrograph and inertia” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s. Volume is 180000 m³ and rise over 22500 m² is 8 m, not a site operating hydrograph. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。","observationEn":"How to cross-check: Compare integrated flow with level rise and relate longitudinal level differences to mooring loads.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s. Volume is 180000 m³ and rise over 22500 m² is 8 m, not a site operating hydrograph.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「充水歷線與慣性」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Filling hydrograph and inertia\", which statement holds?","options":["教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³。","平均輪載足夠低就能排除任何個別輪組超載。","兩澆塊最高溫度相同就表示熱裂縫風險完全相同。"],"optionsEn":["Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s.","Low mean wheel load rules out overload in every individual wheel group.","Two blocks with the same peak temperature have identical thermal-cracking risk."],"answer":0,"explanation":"教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":30},{"id":"b226-v15-07","title":"充水歷線與慣性：試驗與驗證","titleEn":"Filling hydrograph and inertia: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「充水歷線與慣性」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Filling hydrograph and inertia” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。把高頻流量歷線重新取樣後積分，檢查峰值保存程度與總水量的數值收斂。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare integrated flow with level rise and relate longitudinal level differences to mooring loads. Preserve the rising limb resolution instead of smoothing inertial effects into a full-cycle average. Resample the high-frequency hydrograph and integrate it, checking both peak preservation and numerical convergence of total volume. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以充水歷線與慣性編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。","observationEn":"Site practice: Prepare a reviewable evidence sheet for filling hydrograph and inertia, recording data time, units, model applicability and reviewer. Compare integrated flow with level rise and relate longitudinal level differences to mooring loads. Preserve the rising limb resolution instead of smoothing inertial effects into a full-cycle average.","failure":"注意干擾：同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-07-k1","title":"驗證方法","titleEn":"Verification method","text":"用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。把高頻流量歷線重新取樣後積分，檢查峰值保存程度與總水量的數值收斂。","textEn":"Compare integrated flow with level rise and relate longitudinal level differences to mooring loads. Preserve the rising limb resolution instead of smoothing inertial effects into a full-cycle average. Resample the high-frequency hydrograph and integrate it, checking both peak preservation and numerical convergence of total volume.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-07-k2","title":"現場實務","titleEn":"Site practice","text":"以充水歷線與慣性編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。","textEn":"Prepare a reviewable evidence sheet for filling hydrograph and inertia, recording data time, units, model applicability and reviewer. Compare integrated flow with level rise and relate longitudinal level differences to mooring loads. Preserve the rising limb resolution instead of smoothing inertial effects into a full-cycle average.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「充水歷線與慣性」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Filling hydrograph and inertia\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。","百分之六十回用一定讓全年淡水需求直接減少六成。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Compare integrated flow with level rise and relate longitudinal level differences to mooring loads.","Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent."],"answer":1,"explanation":"用流量積分對照水位升幅，並比較室內前後水位差與船舶繫纜負荷；保留流量上升段解析度，避免用整段平均掩蓋慣性效應。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare integrated flow with level rise and relate longitudinal level differences to mooring loads. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":31},{"id":"b226-v15-08","title":"充水歷線與慣性：失效診斷","titleEn":"Filling hydrograph and inertia: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-07"],"objective":"從症狀倒推「充水歷線與慣性」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Filling hydrograph and inertia” and propose discriminating checks, corrective actions and prevention.","instruction":"同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。若僅用完成時間驗收，可能漏掉局部流速、壓力振盪和繫纜張力峰值。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads. Completion time alone misses local velocities, pressure oscillations and maximum mooring tensions during the filling cycle. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：若僅用完成時間驗收，可能漏掉局部流速、壓力振盪和繫纜張力峰值。","observationEn":"Link to the mechanism: Completion time alone misses local velocities, pressure oscillations and maximum mooring tensions during the filling cycle.","failure":"誤判風險：若相信「充水量和總時間相同就表示所有瞬時水力荷載相同。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal filling volume and total duration imply identical transient hydraulic loads.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-08-k1","title":"失效模式","titleEn":"Failure mode","text":"同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。若僅用完成時間驗收，可能漏掉局部流速、壓力振盪和繫纜張力峰值。","textEn":"Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads. Completion time alone misses local velocities, pressure oscillations and maximum mooring tensions during the filling cycle.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「充水歷線與慣性」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Filling hydrograph and inertia\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","閘室平均水位平穩就表示船首船尾沒有壓力差。","同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","A steady mean chamber level means there is no bow-to-stern pressure difference.","Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads."],"answer":2,"explanation":"同一總水量可以由溫和或尖峰歷線達成，船舶受力卻不同。 需以量測區分可能原因。","explanationEn":"Equal total volumes can arise from gentle or peaked hydrographs with different vessel loads. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":32}],"order":5},{"id":"b226-v15-s2","title":"水力機制、材料與定量模型","titleEn":"Hydraulics, materials and quantitative models","description":"本階段聚焦「縱向水面坡度推力」與「密度交換前緣」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Longitudinal water-slope force\" and \"Density-exchange front\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b226-v15-09","title":"縱向水面坡度推力：機制與系統路徑","titleEn":"Longitudinal water-slope force: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-08"],"objective":"說明「縱向水面坡度推力」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Longitudinal water-slope force” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"充水不均會使閘室水面形成坡度，船體承受對應的長向壓力差。以排水重量乘小坡度可估算準靜態推力，但需另外處理流速阻力和繫纜動力。 取重力加速度g=9.81 m/s²。假設船舶排水質量50000 t、閘內坡度0.0002，長向力約mgS=98.1 kN；小坡度準靜態，不含阻力與加速度。 單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。若將全部張力歸於水面坡度，可能掩蓋局部射流或不對稱流入。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「縱向水面坡度推力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uneven filling creates a longitudinal surface slope and pressure imbalance on a vessel. Displacement weight times small slope estimates quasi-static force, with current drag and mooring dynamics treated separately. Use gravitational acceleration g=9.81 m/s². Assume vessel displacement mass 50000 t and longitudinal slope 0.0002. Approximate force mgS=98.1 kN, for a small quasi-static slope without drag or acceleration. A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion. Attributing all tension to slope may conceal a local jet or asymmetric inflow acting on the hull. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Longitudinal water-slope force” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s².","failure":"常見誤解：「閘室平均水位平穩就表示船首船尾沒有壓力差。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A steady mean chamber level means there is no bow-to-stern pressure difference.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「縱向水面坡度推力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Longitudinal water-slope force”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-09-k1","title":"縱向水面坡度推力","titleEn":"Longitudinal water-slope force","text":"充水不均會使閘室水面形成坡度，船體承受對應的長向壓力差。以排水重量乘小坡度可估算準靜態推力，但需另外處理流速阻力和繫纜動力。","textEn":"Uneven filling creates a longitudinal surface slope and pressure imbalance on a vessel. Displacement weight times small slope estimates quasi-static force, with current drag and mooring dynamics treated separately.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：閘室平均水位平穩就表示船首船尾沒有壓力差。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A steady mean chamber level means there is no bow-to-stern pressure difference. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「縱向水面坡度推力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Longitudinal water-slope force\" is correct?","options":["充水不均會使閘室水面形成坡度，船體承受對應的長向壓力差。","閘室平均水位平穩就表示船首船尾沒有壓力差。","兩側水面相同時，不同密度水體就不會互相交換。"],"optionsEn":["Uneven filling creates a longitudinal surface slope and pressure imbalance on a vessel.","A steady mean chamber level means there is no bow-to-stern pressure difference.","Different-density waters stop exchanging when their surface elevations are equal."],"answer":0,"explanation":"充水不均會使閘室水面形成坡度，船體承受對應的長向壓力差。 其餘選項是常見誤解。","explanationEn":"Uneven filling creates a longitudinal surface slope and pressure imbalance on a vessel. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b226-v15-10","title":"縱向水面坡度推力：定量估算","titleEn":"Longitudinal water-slope force: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-09"],"objective":"以數值模型估算「縱向水面坡度推力」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Longitudinal water-slope force” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。假設船舶排水質量50000 t、閘內坡度0.0002，長向力約mgS=98.1 kN；小坡度準靜態，不含阻力與加速度。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Assume vessel displacement mass 50000 t and longitudinal slope 0.0002. Approximate force mgS=98.1 kN, for a small quasi-static slope without drag or acceleration. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。","observationEn":"How to cross-check: Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。假設船舶排水質量50000 t、閘內坡度0.0002，長向力約mgS=98.1 kN；小坡度準靜態，不含阻力與加速度。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Assume vessel displacement mass 50000 t and longitudinal slope 0.0002. Approximate force mgS=98.1 kN, for a small quasi-static slope without drag or acceleration.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「縱向水面坡度推力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Longitudinal water-slope force\", which statement holds?","options":["慢速改變流量也必須產生完整的快速水錘壓峰。","教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。","平均水深足夠就能保證整條船底通道都有足夠淨空。"],"optionsEn":["A slow flow change must generate the full rapid-waterhammer pressure peak.","Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s².","Adequate mean depth guarantees clearance along the entire hull route."],"answer":1,"explanation":"教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":34},{"id":"b226-v15-11","title":"縱向水面坡度推力：試驗與驗證","titleEn":"Longitudinal water-slope force: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「縱向水面坡度推力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Longitudinal water-slope force” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。將船舶質量與坡度推力獨立重算，並檢查繫纜負荷是否存在不屬於水面坡度的相位。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase. Separate wind, propulsion effects and line stiffness to define reproducible comparison conditions. Independently recalculate displacement-slope force and check whether mooring loads contain phases inconsistent with the measured surface slope. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以縱向水面坡度推力編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。","observationEn":"Site practice: Prepare a reviewable evidence sheet for longitudinal water-slope force, recording data time, units, model applicability and reviewer. Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase. Separate wind, propulsion effects and line stiffness to define reproducible comparison conditions.","failure":"注意干擾：單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-11-k1","title":"驗證方法","titleEn":"Verification method","text":"在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。將船舶質量與坡度推力獨立重算，並檢查繫纜負荷是否存在不屬於水面坡度的相位。","textEn":"Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase. Separate wind, propulsion effects and line stiffness to define reproducible comparison conditions. Independently recalculate displacement-slope force and check whether mooring loads contain phases inconsistent with the measured surface slope.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-11-k2","title":"現場實務","titleEn":"Site practice","text":"以縱向水面坡度推力編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。","textEn":"Prepare a reviewable evidence sheet for longitudinal water-slope force, recording data time, units, model applicability and reviewer. Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase. Separate wind, propulsion effects and line stiffness to define reproducible comparison conditions.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「縱向水面坡度推力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Longitudinal water-slope force\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","設備修復後，積壓通行一定能按機械最大吞吐量完成。","在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","After repair the backlog can always clear at maximum mechanical throughput.","Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase."],"answer":2,"explanation":"在船首船尾及中段量測水位與流速，校核坡度估算和繫纜張力相位；將風力、推進器影響與繫纜剛度分離，建立可重現的比較工況。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure levels and currents at bow, stern and midship, comparing inferred slope with mooring-tension phase. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":35},{"id":"b226-v15-12","title":"縱向水面坡度推力：失效診斷","titleEn":"Longitudinal water-slope force: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-11"],"objective":"從症狀倒推「縱向水面坡度推力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Longitudinal water-slope force” and propose discriminating checks, corrective actions and prevention.","instruction":"單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。若將全部張力歸於水面坡度，可能掩蓋局部射流或不對稱流入。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion. Attributing all tension to slope may conceal a local jet or asymmetric inflow acting on the hull. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：若將全部張力歸於水面坡度，可能掩蓋局部射流或不對稱流入。","observationEn":"Link to the mechanism: Attributing all tension to slope may conceal a local jet or asymmetric inflow acting on the hull.","failure":"誤判風險：若相信「閘室平均水位平穩就表示船首船尾沒有壓力差。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A steady mean chamber level means there is no bow-to-stern pressure difference.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-12-k1","title":"失效模式","titleEn":"Failure mode","text":"單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。若將全部張力歸於水面坡度，可能掩蓋局部射流或不對稱流入。","textEn":"A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion. Attributing all tension to slope may conceal a local jet or asymmetric inflow acting on the hull.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「縱向水面坡度推力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Longitudinal water-slope force\" shows distress, which diagnosis is most reasonable?","options":["單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","兩側水面相同時，不同密度水體就不會互相交換。"],"optionsEn":["A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Different-density waters stop exchanging when their surface elevations are equal."],"answer":0,"explanation":"單一水位站無法辨認室內坡度，繫纜伸長也會造成船體動態放大。 需以量測區分可能原因。","explanationEn":"A single gauge cannot resolve chamber slope, and elastic mooring lines can amplify motion. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":36},{"id":"b226-v15-13","title":"密度交換前緣：機制與系統路徑","titleEn":"Density-exchange front: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-12"],"objective":"說明「密度交換前緣」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Density-exchange front” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"海水與淡水連通時，即使兩側表面水位相同，密度差仍可驅動底層鹽水前進和上層淡水返回。這種交換不能用零淨流量判定不存在。 取重力加速度g=9.81 m/s²。假設密度差25 kg/m³、基準1000 kg/m³、水深5 m，約化重力g′=0.24525 m/s²，速度尺度√(g′h)=1.107 m/s；非精確前緣速度。 表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。強紊流又會改變界面厚度，使理想兩層模型失效。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「密度交換前緣」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Connected salt and fresh water can exchange through bottom and surface currents even at equal surface elevations. Zero net discharge therefore does not establish absence of density-driven exchange. Use gravitational acceleration g=9.81 m/s². Assume density difference 25 kg/m³, reference density 1000 kg/m³ and depth 5 m. Reduced gravity is 0.24525 m/s² and √(g′h)=1.107 m/s, a scale rather than an exact front speed. Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate. Strong turbulence thickens the interface and can invalidate an ideal two-layer description of exchange. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Density-exchange front” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s².","failure":"常見誤解：「兩側水面相同時，不同密度水體就不會互相交換。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Different-density waters stop exchanging when their surface elevations are equal.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「密度交換前緣」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Density-exchange front”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-13-k1","title":"密度交換前緣","titleEn":"Density-exchange front","text":"海水與淡水連通時，即使兩側表面水位相同，密度差仍可驅動底層鹽水前進和上層淡水返回。這種交換不能用零淨流量判定不存在。","textEn":"Connected salt and fresh water can exchange through bottom and surface currents even at equal surface elevations. Zero net discharge therefore does not establish absence of density-driven exchange.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩側水面相同時，不同密度水體就不會互相交換。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Different-density waters stop exchanging when their surface elevations are equal. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「密度交換前緣」，下列哪一項敘述正確？","questionEn":"Which statement about \"Density-exchange front\" is correct?","options":["兩側水面相同時，不同密度水體就不會互相交換。","海水與淡水連通時，即使兩側表面水位相同，密度差仍可驅動底層鹽水前進和上層淡水返回。","平均輪載足夠低就能排除任何個別輪組超載。"],"optionsEn":["Different-density waters stop exchanging when their surface elevations are equal.","Connected salt and fresh water can exchange through bottom and surface currents even at equal surface elevations.","Low mean wheel load rules out overload in every individual wheel group."],"answer":1,"explanation":"海水與淡水連通時，即使兩側表面水位相同，密度差仍可驅動底層鹽水前進和上層淡水返回。 其餘選項是常見誤解。","explanationEn":"Connected salt and fresh water can exchange through bottom and surface currents even at equal surface elevations. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b226-v15-14","title":"密度交換前緣：定量估算","titleEn":"Density-exchange front: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-13"],"objective":"以數值模型估算「密度交換前緣」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Density-exchange front” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。假設密度差25 kg/m³、基準1000 kg/m³、水深5 m，約化重力g′=0.24525 m/s²，速度尺度√(g′h)=1.107 m/s；非精確前緣速度。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Assume density difference 25 kg/m³, reference density 1000 kg/m³ and depth 5 m. Reduced gravity is 0.24525 m/s² and √(g′h)=1.107 m/s, a scale rather than an exact front speed. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。","observationEn":"How to cross-check: Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。假設密度差25 kg/m³、基準1000 kg/m³、水深5 m，約化重力g′=0.24525 m/s²，速度尺度√(g′h)=1.107 m/s；非精確前緣速度。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Assume density difference 25 kg/m³, reference density 1000 kg/m³ and depth 5 m. Reduced gravity is 0.24525 m/s² and √(g′h)=1.107 m/s, a scale rather than an exact front speed.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「密度交換前緣」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Density-exchange front\", which statement holds?","options":["兩澆塊最高溫度相同就表示熱裂縫風險完全相同。","百分之六十回用一定讓全年淡水需求直接減少六成。","教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。"],"optionsEn":["Two blocks with the same peak temperature have identical thermal-cracking risk.","Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.","Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s²."],"answer":2,"explanation":"教學假設，非地標實測值或操作設定：取重力加速度g=9.81 m/s²。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Use gravitational acceleration g=9.81 m/s². Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":38},{"id":"b226-v15-15","title":"密度交換前緣：試驗與驗證","titleEn":"Density-exchange front: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「密度交換前緣」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Density-exchange front” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。以分層流量乘鹽度積分鹽通量，確認正負體積流量抵銷時仍可能輸送淨鹽量。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone. Track interactions with vessel displacement and avoid treating turbidity as direct evidence of salinity. Integrate layer flow times salinity and verify that cancelling volume flows can still carry a net salt flux. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以密度交換前緣編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。","observationEn":"Site practice: Prepare a reviewable evidence sheet for density-exchange front, recording data time, units, model applicability and reviewer. Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone. Track interactions with vessel displacement and avoid treating turbidity as direct evidence of salinity.","failure":"注意干擾：表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-15-k1","title":"驗證方法","titleEn":"Verification method","text":"同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。以分層流量乘鹽度積分鹽通量，確認正負體積流量抵銷時仍可能輸送淨鹽量。","textEn":"Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone. Track interactions with vessel displacement and avoid treating turbidity as direct evidence of salinity. Integrate layer flow times salinity and verify that cancelling volume flows can still carry a net salt flux.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-15-k2","title":"現場實務","titleEn":"Site practice","text":"以密度交換前緣編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。","textEn":"Prepare a reviewable evidence sheet for density-exchange front, recording data time, units, model applicability and reviewer. Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone. Track interactions with vessel displacement and avoid treating turbidity as direct evidence of salinity.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「密度交換前緣」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Density-exchange front\"?","options":["同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。","不確定度太難估計，報告中只寫最佳值即可。","節水池即使面積有限，交換水量時水位仍保持不變。"],"optionsEn":["Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone.","Uncertainty is too hard to estimate, so the report may state only the best value.","A finite saving basin maintains constant level while exchanging water."],"answer":0,"explanation":"同時量測上下層流向及鹽度，計算鹽通量而非只積分總流量；追蹤前緣與船舶排水的交互作用，避免把短時混濁當作鹽分證據。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure upper and lower currents and salinity together, calculating salt flux rather than total discharge alone. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":39},{"id":"b226-v15-16","title":"密度交換前緣：失效診斷","titleEn":"Density-exchange front: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-15"],"objective":"從症狀倒推「密度交換前緣」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Density-exchange front” and propose discriminating checks, corrective actions and prevention.","instruction":"表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。強紊流又會改變界面厚度，使理想兩層模型失效。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate. Strong turbulence thickens the interface and can invalidate an ideal two-layer description of exchange. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：強紊流又會改變界面厚度，使理想兩層模型失效。","observationEn":"Link to the mechanism: Strong turbulence thickens the interface and can invalidate an ideal two-layer description of exchange.","failure":"誤判風險：若相信「兩側水面相同時，不同密度水體就不會互相交換。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Different-density waters stop exchanging when their surface elevations are equal.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-16-k1","title":"失效模式","titleEn":"Failure mode","text":"表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。強紊流又會改變界面厚度，使理想兩層模型失效。","textEn":"Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate. Strong turbulence thickens the interface and can invalidate an ideal two-layer description of exchange.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「密度交換前緣」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Density-exchange front\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。","平均輪載足夠低就能排除任何個別輪組超載。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate.","Low mean wheel load rules out overload in every individual wheel group."],"answer":1,"explanation":"表層看似沒有入流時底層仍可向內輸送鹽分，傳感器只設單一深度會漏判。 需以量測區分可能原因。","explanationEn":"Salt can enter along the bed while the surface appears still, making one-depth sensing inadequate. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":40}],"order":6},{"id":"b226-v15-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「閘門浮力與輪載」與「管路快速減速壓峰」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Gate buoyancy and wheel loads\" and \"Rapid conduit deceleration pressure\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b226-v15-17","title":"閘門浮力與輪載：機制與系統路徑","titleEn":"Gate buoyancy and wheel loads: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-16"],"objective":"說明「閘門浮力與輪載」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Gate buoyancy and wheel loads” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"滾動門靠輪組與浮力共同承受重量，水位改變會重新分配輪載。減輕平均輪載有利移動，但偏心、軌道沉降和門體變形仍可能使個別輪子受力集中。 假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。 某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。浮力艙漏水也可能增加荷載而不立即停止運動，所以移動成功不能代替承載檢查。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「閘門浮力與輪載」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Rolling gates share weight between buoyancy and wheel groups, with levels changing wheel loads. Lower mean loading aids movement, but eccentricity, rail settlement and deformation can still concentrate reactions on individual wheels. Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels. Mean wheel load is (40−28)/8=1.5 MN, excluding eccentricity, dynamics and rail-level differences. A lifted wheel transfers load to others while the average formula still appears normal. A leaking buoyancy compartment can increase loading without stopping motion, so movement success cannot replace bearing assessment. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Gate buoyancy and wheel loads” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels.","failure":"常見誤解：「平均輪載足夠低就能排除任何個別輪組超載。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Low mean wheel load rules out overload in every individual wheel group.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「閘門浮力與輪載」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Gate buoyancy and wheel loads”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-17-k1","title":"閘門浮力與輪載","titleEn":"Gate buoyancy and wheel loads","text":"滾動門靠輪組與浮力共同承受重量，水位改變會重新分配輪載。減輕平均輪載有利移動，但偏心、軌道沉降和門體變形仍可能使個別輪子受力集中。","textEn":"Rolling gates share weight between buoyancy and wheel groups, with levels changing wheel loads. Lower mean loading aids movement, but eccentricity, rail settlement and deformation can still concentrate reactions on individual wheels.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：平均輪載足夠低就能排除任何個別輪組超載。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Low mean wheel load rules out overload in every individual wheel group. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「閘門浮力與輪載」，下列哪一項敘述正確？","questionEn":"Which statement about \"Gate buoyancy and wheel loads\" is correct?","options":["平均輪載足夠低就能排除任何個別輪組超載。","慢速改變流量也必須產生完整的快速水錘壓峰。","滾動門靠輪組與浮力共同承受重量，水位改變會重新分配輪載。"],"optionsEn":["Low mean wheel load rules out overload in every individual wheel group.","A slow flow change must generate the full rapid-waterhammer pressure peak.","Rolling gates share weight between buoyancy and wheel groups, with levels changing wheel loads."],"answer":2,"explanation":"滾動門靠輪組與浮力共同承受重量，水位改變會重新分配輪載。 其餘選項是常見誤解。","explanationEn":"Rolling gates share weight between buoyancy and wheel groups, with levels changing wheel loads. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":41},{"id":"b226-v15-18","title":"閘門浮力與輪載：定量估算","titleEn":"Gate buoyancy and wheel loads: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-17"],"objective":"以數值模型估算「閘門浮力與輪載」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Gate buoyancy and wheel loads” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels. Mean wheel load is (40−28)/8=1.5 MN, excluding eccentricity, dynamics and rail-level differences. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。","observationEn":"How to cross-check: Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels. Mean wheel load is (40−28)/8=1.5 MN, excluding eccentricity, dynamics and rail-level differences.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「閘門浮力與輪載」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Gate buoyancy and wheel loads\", which statement holds?","options":["教學假設，非地標實測值或操作設定：假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。","平均水深足夠就能保證整條船底通道都有足夠淨空。","設備修復後，積壓通行一定能按機械最大吞吐量完成。"],"optionsEn":["Teaching assumptions, not landmark measurements or operating settings: Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels.","Adequate mean depth guarantees clearance along the entire hull route.","After repair the backlog can always clear at maximum mechanical throughput."],"answer":0,"explanation":"教學假設，非地標實測值或操作設定：假設門重40 MN、浮力28 MN、8輪理想均分，平均輪載(40−28)/8=1.5 MN；不含偏心、動力或軌道高差。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume gate weight 40 MN, buoyancy 28 MN and eight equally sharing wheels. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":42},{"id":"b226-v15-19","title":"閘門浮力與輪載：試驗與驗證","titleEn":"Gate buoyancy and wheel loads: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「閘門浮力與輪載」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Gate buoyancy and wheel loads” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。比較各輪反力總和與扣除浮力後的重量，另檢查最大輪載是否隨軌道高點移動。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact. Verify total reaction equilibrium before evaluating maximum individual loads rather than averages. Compare summed reactions with weight minus buoyancy and check whether maximum wheel load follows rail high spots. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以閘門浮力與輪載編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。","observationEn":"Site practice: Prepare a reviewable evidence sheet for gate buoyancy and wheel loads, recording data time, units, model applicability and reviewer. Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact. Verify total reaction equilibrium before evaluating maximum individual loads rather than averages.","failure":"注意干擾：某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A lifted wheel transfers load to others while the average formula still appears normal. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-19-k1","title":"驗證方法","titleEn":"Verification method","text":"將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。比較各輪反力總和與扣除浮力後的重量，另檢查最大輪載是否隨軌道高點移動。","textEn":"Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact. Verify total reaction equilibrium before evaluating maximum individual loads rather than averages. Compare summed reactions with weight minus buoyancy and check whether maximum wheel load follows rail high spots.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-19-k2","title":"現場實務","titleEn":"Site practice","text":"以閘門浮力與輪載編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。","textEn":"Prepare a reviewable evidence sheet for gate buoyancy and wheel loads, recording data time, units, model applicability and reviewer. Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact. Verify total reaction equilibrium before evaluating maximum individual loads rather than averages.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「閘門浮力與輪載」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Gate buoyancy and wheel loads\"?","options":["允收準則可以等看到量測數據後再決定。","將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。","充水量和總時間相同就表示所有瞬時水力荷載相同。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact.","Equal filling volume and total duration imply identical transient hydraulic loads."],"answer":1,"explanation":"將輪載或軸承應變與水位、門位一起比對，檢查軌道高程和各輪接觸；以總反力守恆確認量測，再評估最大輪載而非平均值。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare wheel loads or bearing strains with water level and position, checking rail elevation and wheel contact. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":43},{"id":"b226-v15-20","title":"閘門浮力與輪載：失效診斷","titleEn":"Gate buoyancy and wheel loads: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-19"],"objective":"從症狀倒推「閘門浮力與輪載」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Gate buoyancy and wheel loads” and propose discriminating checks, corrective actions and prevention.","instruction":"某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。浮力艙漏水也可能增加荷載而不立即停止運動，所以移動成功不能代替承載檢查。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A lifted wheel transfers load to others while the average formula still appears normal. A leaking buoyancy compartment can increase loading without stopping motion, so movement success cannot replace bearing assessment. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：浮力艙漏水也可能增加荷載而不立即停止運動，所以移動成功不能代替承載檢查。","observationEn":"Link to the mechanism: A leaking buoyancy compartment can increase loading without stopping motion, so movement success cannot replace bearing assessment.","failure":"誤判風險：若相信「平均輪載足夠低就能排除任何個別輪組超載。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Low mean wheel load rules out overload in every individual wheel group.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-20-k1","title":"失效模式","titleEn":"Failure mode","text":"某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。浮力艙漏水也可能增加荷載而不立即停止運動，所以移動成功不能代替承載檢查。","textEn":"A lifted wheel transfers load to others while the average formula still appears normal. A leaking buoyancy compartment can increase loading without stopping motion, so movement success cannot replace bearing assessment.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「閘門浮力與輪載」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Gate buoyancy and wheel loads\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","慢速改變流量也必須產生完整的快速水錘壓峰。","某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A slow flow change must generate the full rapid-waterhammer pressure peak.","A lifted wheel transfers load to others while the average formula still appears normal."],"answer":2,"explanation":"某輪懸空會把荷載轉給其他輪，平均公式仍可能看似正常。 需以量測區分可能原因。","explanationEn":"A lifted wheel transfers load to others while the average formula still appears normal. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":44},{"id":"b226-v15-21","title":"管路快速減速壓峰：機制與系統路徑","titleEn":"Rapid conduit deceleration pressure: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-20"],"objective":"說明「管路快速減速壓峰」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Rapid conduit deceleration pressure” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"充洩水管路的速度改變會形成壓力波，反射邊界和含氣量決定波速與衰減。Joukowsky式適合快速改變的初估，慢速閥動作須用歷時模型。 假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa；非閥門操作設定。 若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。把壓力計阻尼造成的平滑當成真實衰減也會低估荷載。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「管路快速減速壓峰」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Velocity changes in filling conduits create pressure waves whose speed and decay depend on boundaries and air content. Joukowsky gives a rapid-change estimate; slower valve motion requires time-dependent analysis. Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting. Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate. Sensor damping mistaken for physical decay can also underestimate the actual transient load. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Rapid conduit deceleration pressure” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa；非閥門操作設定。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting.","failure":"常見誤解：「慢速改變流量也必須產生完整的快速水錘壓峰。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A slow flow change must generate the full rapid-waterhammer pressure peak.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「管路快速減速壓峰」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Rapid conduit deceleration pressure”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-21-k1","title":"管路快速減速壓峰","titleEn":"Rapid conduit deceleration pressure","text":"充洩水管路的速度改變會形成壓力波，反射邊界和含氣量決定波速與衰減。Joukowsky式適合快速改變的初估，慢速閥動作須用歷時模型。","textEn":"Velocity changes in filling conduits create pressure waves whose speed and decay depend on boundaries and air content. Joukowsky gives a rapid-change estimate; slower valve motion requires time-dependent analysis.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：慢速改變流量也必須產生完整的快速水錘壓峰。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A slow flow change must generate the full rapid-waterhammer pressure peak. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「管路快速減速壓峰」，下列哪一項敘述正確？","questionEn":"Which statement about \"Rapid conduit deceleration pressure\" is correct?","options":["充洩水管路的速度改變會形成壓力波，反射邊界和含氣量決定波速與衰減。","慢速改變流量也必須產生完整的快速水錘壓峰。","兩澆塊最高溫度相同就表示熱裂縫風險完全相同。"],"optionsEn":["Velocity changes in filling conduits create pressure waves whose speed and decay depend on boundaries and air content.","A slow flow change must generate the full rapid-waterhammer pressure peak.","Two blocks with the same peak temperature have identical thermal-cracking risk."],"answer":0,"explanation":"充洩水管路的速度改變會形成壓力波，反射邊界和含氣量決定波速與衰減。 其餘選項是常見誤解。","explanationEn":"Velocity changes in filling conduits create pressure waves whose speed and decay depend on boundaries and air content. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":45},{"id":"b226-v15-22","title":"管路快速減速壓峰：定量估算","titleEn":"Rapid conduit deceleration pressure: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-21"],"objective":"以數值模型估算「管路快速減速壓峰」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Rapid conduit deceleration pressure” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa；非閥門操作設定。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。","observationEn":"How to cross-check: Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa；非閥門操作設定。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「管路快速減速壓峰」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Rapid conduit deceleration pressure\", which statement holds?","options":["百分之六十回用一定讓全年淡水需求直接減少六成。","教學假設，非地標實測值或操作設定：假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa。","節水池即使面積有限，交換水量時水位仍保持不變。"],"optionsEn":["Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.","Teaching assumptions, not landmark measurements or operating settings: Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting.","A finite saving basin maintains constant level while exchanging water."],"answer":1,"explanation":"教學假設，非地標實測值或操作設定：假設ρ=1000 kg/m³、波速800 m/s、速度減少0.3 m/s且變化快於2L/a，Δp=ρaΔv=240 kPa；非閥門操作設定。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume density 1000 kg/m³, wave speed 800 m/s and velocity change 0.3 m/s occurring faster than 2L/a. Δp=ρaΔv=240 kPa, not a valve operating setting. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":46},{"id":"b226-v15-23","title":"管路快速減速壓峰：試驗與驗證","titleEn":"Rapid conduit deceleration pressure: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「管路快速減速壓峰」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Rapid conduit deceleration pressure” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。以壓波往返時間核對閥動作快慢分類，並用多站到達時差反算有效波速。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations. Verify adequate sampling and distinguish vapor cavities from the single-phase elastic model. Compare valve movement time with wave round-trip time and infer effective wave speed from multi-station arrival differences. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以管路快速減速壓峰編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。","observationEn":"Site practice: Prepare a reviewable evidence sheet for rapid conduit deceleration pressure, recording data time, units, model applicability and reviewer. Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations. Verify adequate sampling and distinguish vapor cavities from the single-phase elastic model.","failure":"注意干擾：若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-23-k1","title":"驗證方法","titleEn":"Verification method","text":"核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。以壓波往返時間核對閥動作快慢分類，並用多站到達時差反算有效波速。","textEn":"Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations. Verify adequate sampling and distinguish vapor cavities from the single-phase elastic model. Compare valve movement time with wave round-trip time and infer effective wave speed from multi-station arrival differences.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-23-k2","title":"現場實務","titleEn":"Site practice","text":"以管路快速減速壓峰編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。","textEn":"Prepare a reviewable evidence sheet for rapid conduit deceleration pressure, recording data time, units, model applicability and reviewer. Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations. Verify adequate sampling and distinguish vapor cavities from the single-phase elastic model.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「管路快速減速壓峰」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Rapid conduit deceleration pressure\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","閘室平均水位平穩就表示船首船尾沒有壓力差。","核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","A steady mean chamber level means there is no bow-to-stern pressure difference.","Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations."],"answer":2,"explanation":"核對管長、波速和動作歷時，再比較多點壓力到達時間與反射；檢查記錄取樣率足以看到波峰，並辨識氣穴與單相彈性模型的差別。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check pipe length, wave speed and movement duration, comparing pressure arrival and reflection at several locations. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":47},{"id":"b226-v15-24","title":"管路快速減速壓峰：失效診斷","titleEn":"Rapid conduit deceleration pressure: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-23"],"objective":"從症狀倒推「管路快速減速壓峰」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Rapid conduit deceleration pressure” and propose discriminating checks, corrective actions and prevention.","instruction":"若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。把壓力計阻尼造成的平滑當成真實衰減也會低估荷載。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate. Sensor damping mistaken for physical decay can also underestimate the actual transient load. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：把壓力計阻尼造成的平滑當成真實衰減也會低估荷載。","observationEn":"Link to the mechanism: Sensor damping mistaken for physical decay can also underestimate the actual transient load.","failure":"誤判風險：若相信「慢速改變流量也必須產生完整的快速水錘壓峰。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A slow flow change must generate the full rapid-waterhammer pressure peak.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-24-k1","title":"失效模式","titleEn":"Failure mode","text":"若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。把壓力計阻尼造成的平滑當成真實衰減也會低估荷載。","textEn":"Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate. Sensor damping mistaken for physical decay can also underestimate the actual transient load.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「管路快速減速壓峰」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Rapid conduit deceleration pressure\" shows distress, which diagnosis is most reasonable?","options":["若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。","只要結構還沒倒，就代表安全餘裕仍然足夠。","兩澆塊最高溫度相同就表示熱裂縫風險完全相同。"],"optionsEn":["Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate.","As long as the structure is still standing, its safety margin must still be adequate.","Two blocks with the same peak temperature have identical thermal-cracking risk."],"answer":0,"explanation":"若壓力降至汽化壓以下，水柱分離後再碰撞可能產生不同峰值，單次線性式失效。 需以量測區分可能原因。","explanationEn":"Column separation below vapor pressure and subsequent recombination can create different peaks, invalidating a single linear estimate. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":48}],"order":7},{"id":"b226-v15-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「混凝土溫差拘束」與「船底餘裕與沉降量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Concrete thermal restraint\" and \"Under-keel clearance and squat\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b226-v15-25","title":"混凝土溫差拘束：機制與系統路徑","titleEn":"Concrete thermal restraint: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-24"],"objective":"說明「混凝土溫差拘束」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Concrete thermal restraint” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"大型閘室牆體的溫度收縮受底板與相鄰澆塊拘束，裂縫風險取決於拘束和早齡強度發展。只看最高溫度會漏掉冷卻過程的拉應力。 假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa；彈性近似，未含徐變鬆弛。 表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。以成熟度單值代替拉伸能力容易誤判。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「混凝土溫差拘束」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Large lock walls contract against foundations and adjoining blocks. Crack risk depends on restraint and developing early-age strength, so peak temperature alone misses tensile demand during cooling. Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4. Stress REαΔT=1.5 MPa, an elastic estimate without creep relaxation. Rapid surface cooling can crack concrete despite a small mean drop. Creep reduces some stresses but does not guarantee watertight joints, and one maturity value cannot substitute for tensile capacity. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Concrete thermal restraint” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa；彈性近似，未含徐變鬆弛。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4.","failure":"常見誤解：「兩澆塊最高溫度相同就表示熱裂縫風險完全相同。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Two blocks with the same peak temperature have identical thermal-cracking risk.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「混凝土溫差拘束」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Concrete thermal restraint”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-25-k1","title":"混凝土溫差拘束","titleEn":"Concrete thermal restraint","text":"大型閘室牆體的溫度收縮受底板與相鄰澆塊拘束，裂縫風險取決於拘束和早齡強度發展。只看最高溫度會漏掉冷卻過程的拉應力。","textEn":"Large lock walls contract against foundations and adjoining blocks. Crack risk depends on restraint and developing early-age strength, so peak temperature alone misses tensile demand during cooling.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩澆塊最高溫度相同就表示熱裂縫風險完全相同。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Two blocks with the same peak temperature have identical thermal-cracking risk. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「混凝土溫差拘束」，下列哪一項敘述正確？","questionEn":"Which statement about \"Concrete thermal restraint\" is correct?","options":["兩澆塊最高溫度相同就表示熱裂縫風險完全相同。","大型閘室牆體的溫度收縮受底板與相鄰澆塊拘束，裂縫風險取決於拘束和早齡強度發展。","平均水深足夠就能保證整條船底通道都有足夠淨空。"],"optionsEn":["Two blocks with the same peak temperature have identical thermal-cracking risk.","Large lock walls contract against foundations and adjoining blocks.","Adequate mean depth guarantees clearance along the entire hull route."],"answer":1,"explanation":"大型閘室牆體的溫度收縮受底板與相鄰澆塊拘束，裂縫風險取決於拘束和早齡強度發展。 其餘選項是常見誤解。","explanationEn":"Large lock walls contract against foundations and adjoining blocks. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":49},{"id":"b226-v15-26","title":"混凝土溫差拘束：定量估算","titleEn":"Concrete thermal restraint: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-25"],"objective":"以數值模型估算「混凝土溫差拘束」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Concrete thermal restraint” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa；彈性近似，未含徐變鬆弛。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4. Stress REαΔT=1.5 MPa, an elastic estimate without creep relaxation. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。","observationEn":"How to cross-check: Compare core and surface temperatures, joint movement and age-dependent strength synchronously.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa；彈性近似，未含徐變鬆弛。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4. Stress REαΔT=1.5 MPa, an elastic estimate without creep relaxation.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「混凝土溫差拘束」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Concrete thermal restraint\", which statement holds?","options":["設備修復後，積壓通行一定能按機械最大吞吐量完成。","充水量和總時間相同就表示所有瞬時水力荷載相同。","教學假設，非地標實測值或操作設定：假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa。"],"optionsEn":["After repair the backlog can always clear at maximum mechanical throughput.","Equal filling volume and total duration imply identical transient hydraulic loads.","Teaching assumptions, not landmark measurements or operating settings: Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4."],"answer":2,"explanation":"教學假設，非地標實測值或操作設定：假設E=25 GPa、熱膨脹係數10⁻⁵/K、降溫15 K、有效拘束0.4，σ=REαΔT=1.5 MPa；彈性近似，未含徐變鬆弛。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume E=25 GPa, thermal expansion 10⁻⁵/K, cooling 15 K and effective restraint 0.4. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":50},{"id":"b226-v15-27","title":"混凝土溫差拘束：試驗與驗證","titleEn":"Concrete thermal restraint: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「混凝土溫差拘束」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Concrete thermal restraint” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。以齡期相符的模數與拉伸資料重新計算，檢查溫降、拘束與開裂時間是否一致。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare core and surface temperatures, joint movement and age-dependent strength synchronously. Distinguish internal gradients from overall restraint and use material tests to update modulus and curing boundaries. Recalculate using age-matched modulus and tensile data and check consistency between cooling, restraint and observed crack timing. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以混凝土溫差拘束編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。","observationEn":"Site practice: Prepare a reviewable evidence sheet for concrete thermal restraint, recording data time, units, model applicability and reviewer. Compare core and surface temperatures, joint movement and age-dependent strength synchronously. Distinguish internal gradients from overall restraint and use material tests to update modulus and curing boundaries.","failure":"注意干擾：表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Rapid surface cooling can crack concrete despite a small mean drop. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-27-k1","title":"驗證方法","titleEn":"Verification method","text":"將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。以齡期相符的模數與拉伸資料重新計算，檢查溫降、拘束與開裂時間是否一致。","textEn":"Compare core and surface temperatures, joint movement and age-dependent strength synchronously. Distinguish internal gradients from overall restraint and use material tests to update modulus and curing boundaries. Recalculate using age-matched modulus and tensile data and check consistency between cooling, restraint and observed crack timing.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-27-k2","title":"現場實務","titleEn":"Site practice","text":"以混凝土溫差拘束編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。","textEn":"Prepare a reviewable evidence sheet for concrete thermal restraint, recording data time, units, model applicability and reviewer. Compare core and surface temperatures, joint movement and age-dependent strength synchronously. Distinguish internal gradients from overall restraint and use material tests to update modulus and curing boundaries.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「混凝土溫差拘束」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Concrete thermal restraint\"?","options":["將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","兩側水面相同時，不同密度水體就不會互相交換。"],"optionsEn":["Compare core and surface temperatures, joint movement and age-dependent strength synchronously.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Different-density waters stop exchanging when their surface elevations are equal."],"answer":0,"explanation":"將核心與表面溫度、接縫位移和齡期強度同步比較，辨認內外溫差與整體拘束；使用實際材料試驗修正模數，保留養護期間邊界。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare core and surface temperatures, joint movement and age-dependent strength synchronously. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":51},{"id":"b226-v15-28","title":"混凝土溫差拘束：失效診斷","titleEn":"Concrete thermal restraint: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-27"],"objective":"從症狀倒推「混凝土溫差拘束」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Concrete thermal restraint” and propose discriminating checks, corrective actions and prevention.","instruction":"表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。以成熟度單值代替拉伸能力容易誤判。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Rapid surface cooling can crack concrete despite a small mean drop. Creep reduces some stresses but does not guarantee watertight joints, and one maturity value cannot substitute for tensile capacity. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：以成熟度單值代替拉伸能力容易誤判。","observationEn":"Link to the mechanism: Creep reduces some stresses but does not guarantee watertight joints, and one maturity value cannot substitute for tensile capacity.","failure":"誤判風險：若相信「兩澆塊最高溫度相同就表示熱裂縫風險完全相同。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Two blocks with the same peak temperature have identical thermal-cracking risk.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-28-k1","title":"失效模式","titleEn":"Failure mode","text":"表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。以成熟度單值代替拉伸能力容易誤判。","textEn":"Rapid surface cooling can crack concrete despite a small mean drop. Creep reduces some stresses but does not guarantee watertight joints, and one maturity value cannot substitute for tensile capacity.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「混凝土溫差拘束」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Concrete thermal restraint\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。","平均水深足夠就能保證整條船底通道都有足夠淨空。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Rapid surface cooling can crack concrete despite a small mean drop.","Adequate mean depth guarantees clearance along the entire hull route."],"answer":1,"explanation":"表面快速冷卻會造成局部裂縫，即使整體平均溫降不大；徐變雖降低短時應力，也不能保證止水接縫保持完整。 需以量測區分可能原因。","explanationEn":"Rapid surface cooling can crack concrete despite a small mean drop. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":52},{"id":"b226-v15-29","title":"船底餘裕與沉降量：機制與系統路徑","titleEn":"Under-keel clearance and squat: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-28"],"objective":"說明「船底餘裕與沉降量」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Under-keel clearance and squat” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"船底淨空由水深減吃水和動態變化決定，載重、鹽度和航速都會影響結果。幾何餘裕不是可直接使用的航行餘裕，須分列波動與量測不確定度。 假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m；全部為假設。 沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。若把固定吃水值用於所有載重與水質，會產生不實的可用餘裕。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「船底餘裕與沉降量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Under-keel clearance subtracts draft and dynamic effects from depth, with loading, salinity and speed all relevant. Geometric clearance differs from usable navigation margin, requiring separate motion and measurement allowances. Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m. Available margin is 16−14.5−0.25−0.35=0.90 m, with all values assumed. A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft. Fixed draft across different loads and water conditions creates a misleading available margin. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Under-keel clearance and squat” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m；全部為假設。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m.","failure":"常見誤解：「平均水深足夠就能保證整條船底通道都有足夠淨空。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Adequate mean depth guarantees clearance along the entire hull route.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「船底餘裕與沉降量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Under-keel clearance and squat”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-29-k1","title":"船底餘裕與沉降量","titleEn":"Under-keel clearance and squat","text":"船底淨空由水深減吃水和動態變化決定，載重、鹽度和航速都會影響結果。幾何餘裕不是可直接使用的航行餘裕，須分列波動與量測不確定度。","textEn":"Under-keel clearance subtracts draft and dynamic effects from depth, with loading, salinity and speed all relevant. Geometric clearance differs from usable navigation margin, requiring separate motion and measurement allowances.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：平均水深足夠就能保證整條船底通道都有足夠淨空。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Adequate mean depth guarantees clearance along the entire hull route. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「船底餘裕與沉降量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Under-keel clearance and squat\" is correct?","options":["平均水深足夠就能保證整條船底通道都有足夠淨空。","百分之六十回用一定讓全年淡水需求直接減少六成。","船底淨空由水深減吃水和動態變化決定，載重、鹽度和航速都會影響結果。"],"optionsEn":["Adequate mean depth guarantees clearance along the entire hull route.","Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.","Under-keel clearance subtracts draft and dynamic effects from depth, with loading, salinity and speed all relevant."],"answer":2,"explanation":"船底淨空由水深減吃水和動態變化決定，載重、鹽度和航速都會影響結果。 其餘選項是常見誤解。","explanationEn":"Under-keel clearance subtracts draft and dynamic effects from depth, with loading, salinity and speed all relevant. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":53},{"id":"b226-v15-30","title":"船底餘裕與沉降量：定量估算","titleEn":"Under-keel clearance and squat: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-29"],"objective":"以數值模型估算「船底餘裕與沉降量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Under-keel clearance and squat” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m；全部為假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m. Available margin is 16−14.5−0.25−0.35=0.90 m, with all values assumed. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。","observationEn":"How to cross-check: Align depth, draft and tide references and times, checking highest bed points rather than mean depth.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m；全部為假設。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m. Available margin is 16−14.5−0.25−0.35=0.90 m, with all values assumed.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「船底餘裕與沉降量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Under-keel clearance and squat\", which statement holds?","options":["教學假設，非地標實測值或操作設定：假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m。","節水池即使面積有限，交換水量時水位仍保持不變。","閘室平均水位平穩就表示船首船尾沒有壓力差。"],"optionsEn":["Teaching assumptions, not landmark measurements or operating settings: Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m.","A finite saving basin maintains constant level while exchanging water.","A steady mean chamber level means there is no bow-to-stern pressure difference."],"answer":0,"explanation":"教學假設，非地標實測值或操作設定：假設水深16 m、吃水14.5 m、動態下沉0.25 m、其他保留0.35 m，可用餘裕16−14.5−0.25−0.35=0.90 m；全部為假設。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume depth 16 m, draft 14.5 m, squat 0.25 m and other allowance 0.35 m. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":54},{"id":"b226-v15-31","title":"船底餘裕與沉降量：試驗與驗證","titleEn":"Under-keel clearance and squat: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「船底餘裕與沉降量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Under-keel clearance and squat” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。對測深誤差和吃水變化分別作敏感度分析，核對最不利位置而非只有代表斷面。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Align depth, draft and tide references and times, checking highest bed points rather than mean depth. Retain trim, motion and sounding uncertainty separately to avoid duplicated or omitted deductions. Test sounding-error and draft sensitivities separately and assess the controlling location rather than one representative section. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以船底餘裕與沉降量編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。","observationEn":"Site practice: Prepare a reviewable evidence sheet for under-keel clearance and squat, recording data time, units, model applicability and reviewer. Align depth, draft and tide references and times, checking highest bed points rather than mean depth. Retain trim, motion and sounding uncertainty separately to avoid duplicated or omitted deductions.","failure":"注意干擾：沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-31-k1","title":"驗證方法","titleEn":"Verification method","text":"統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。對測深誤差和吃水變化分別作敏感度分析，核對最不利位置而非只有代表斷面。","textEn":"Align depth, draft and tide references and times, checking highest bed points rather than mean depth. Retain trim, motion and sounding uncertainty separately to avoid duplicated or omitted deductions. Test sounding-error and draft sensitivities separately and assess the controlling location rather than one representative section.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-31-k2","title":"現場實務","titleEn":"Site practice","text":"以船底餘裕與沉降量編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。","textEn":"Prepare a reviewable evidence sheet for under-keel clearance and squat, recording data time, units, model applicability and reviewer. Align depth, draft and tide references and times, checking highest bed points rather than mean depth. Retain trim, motion and sounding uncertainty separately to avoid duplicated or omitted deductions.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「船底餘裕與沉降量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Under-keel clearance and squat\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。","平均輪載足夠低就能排除任何個別輪組超載。"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Align depth, draft and tide references and times, checking highest bed points rather than mean depth.","Low mean wheel load rules out overload in every individual wheel group."],"answer":1,"explanation":"統一水深、吃水和潮位的基準與時刻，查底床最高點而非平均深度；將船體縱傾、波動和測深誤差分別保存，避免重複或遺漏扣減。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Align depth, draft and tide references and times, checking highest bed points rather than mean depth. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":55},{"id":"b226-v15-32","title":"船底餘裕與沉降量：失效診斷","titleEn":"Under-keel clearance and squat: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-31"],"objective":"從症狀倒推「船底餘裕與沉降量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Under-keel clearance and squat” and propose discriminating checks, corrective actions and prevention.","instruction":"沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。若把固定吃水值用於所有載重與水質，會產生不實的可用餘裕。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft. Fixed draft across different loads and water conditions creates a misleading available margin. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：若把固定吃水值用於所有載重與水質，會產生不實的可用餘裕。","observationEn":"Link to the mechanism: Fixed draft across different loads and water conditions creates a misleading available margin.","failure":"誤判風險：若相信「平均水深足夠就能保證整條船底通道都有足夠淨空。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Adequate mean depth guarantees clearance along the entire hull route.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-32-k1","title":"失效模式","titleEn":"Failure mode","text":"沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。若把固定吃水值用於所有載重與水質，會產生不實的可用餘裕。","textEn":"A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft. Fixed draft across different loads and water conditions creates a misleading available margin.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「船底餘裕與沉降量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Under-keel clearance and squat\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","百分之六十回用一定讓全年淡水需求直接減少六成。","沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.","A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft."],"answer":2,"explanation":"沉積高點可能在水深平均值仍足夠時造成局部淺區，密度改變亦會增加吃水。 需以量測區分可能原因。","explanationEn":"A deposit high spot can create a shallow patch despite adequate mean depth, and density changes alter draft. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":56}],"order":8},{"id":"b226-v15-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「回用率與淨淡水耗用」與「故障停航與水源緩衝」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Reuse ratio and net freshwater use\" and \"Outage backlog and water reserve\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b226-v15-33","title":"回用率與淨淡水耗用：機制與系統路徑","titleEn":"Reuse ratio and net freshwater use: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-32"],"objective":"說明「回用率與淨淡水耗用」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Reuse ratio and net freshwater use” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"回用百分比必須有明確分母，閘室交換量、從湖取水量與全年水源消耗並不相同。漏流、蒸發與鹽分管理可能改變系統邊界內的淨耗用。 假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³；非官方每次用水量。 只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。閘次船型差異和不完整循環又可能造成看似改善卻不可比較的績效數字。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「回用率與淨淡水耗用」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A reuse percentage requires an explicit denominator. Chamber exchange, lake withdrawal and annual water-resource consumption differ, while leakage, evaporation and salinity management can change net use within the chosen boundary. Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³. Freshwater makeup is (1−0.6)200000+5000=85000 m³, not an official lockage demand. Quoting reuse alone confuses cycle hydraulics with watershed savings. Vessel differences and incomplete cycles can produce apparently improved performance values that are not comparable across the measurement period. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Reuse ratio and net freshwater use” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³；非官方每次用水量。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³.","failure":"常見誤解：「百分之六十回用一定讓全年淡水需求直接減少六成。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「回用率與淨淡水耗用」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Reuse ratio and net freshwater use”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-33-k1","title":"回用率與淨淡水耗用","titleEn":"Reuse ratio and net freshwater use","text":"回用百分比必須有明確分母，閘室交換量、從湖取水量與全年水源消耗並不相同。漏流、蒸發與鹽分管理可能改變系統邊界內的淨耗用。","textEn":"A reuse percentage requires an explicit denominator. Chamber exchange, lake withdrawal and annual water-resource consumption differ, while leakage, evaporation and salinity management can change net use within the chosen boundary.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：百分之六十回用一定讓全年淡水需求直接減少六成。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「回用率與淨淡水耗用」，下列哪一項敘述正確？","questionEn":"Which statement about \"Reuse ratio and net freshwater use\" is correct?","options":["回用百分比必須有明確分母，閘室交換量、從湖取水量與全年水源消耗並不相同。","百分之六十回用一定讓全年淡水需求直接減少六成。","設備修復後，積壓通行一定能按機械最大吞吐量完成。"],"optionsEn":["A reuse percentage requires an explicit denominator.","Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.","After repair the backlog can always clear at maximum mechanical throughput."],"answer":0,"explanation":"回用百分比必須有明確分母，閘室交換量、從湖取水量與全年水源消耗並不相同。 其餘選項是常見誤解。","explanationEn":"A reuse percentage requires an explicit denominator. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":57},{"id":"b226-v15-34","title":"回用率與淨淡水耗用：定量估算","titleEn":"Reuse ratio and net freshwater use: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-33"],"objective":"以數值模型估算「回用率與淨淡水耗用」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Reuse ratio and net freshwater use” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³；非官方每次用水量。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³. Freshwater makeup is (1−0.6)200000+5000=85000 m³, not an official lockage demand. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。","observationEn":"How to cross-check: Map every water source and destination, separating basins, sea and freshwater lake into control volumes.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³；非官方每次用水量。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³. Freshwater makeup is (1−0.6)200000+5000=85000 m³, not an official lockage demand.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「回用率與淨淡水耗用」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Reuse ratio and net freshwater use\", which statement holds?","options":["充水量和總時間相同就表示所有瞬時水力荷載相同。","教學假設，非地標實測值或操作設定：假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³。","兩側水面相同時，不同密度水體就不會互相交換。"],"optionsEn":["Equal filling volume and total duration imply identical transient hydraulic loads.","Teaching assumptions, not landmark measurements or operating settings: Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³.","Different-density waters stop exchanging when their surface elevations are equal."],"answer":1,"explanation":"教學假設，非地標實測值或操作設定：假設一次交換量200000 m³、回用率0.6、另有損失5000 m³，淡水補充=(1−0.6)200000+5000=85000 m³；非官方每次用水量。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume cycle exchange 200000 m³, reuse fraction 0.6 and other losses 5000 m³. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":58},{"id":"b226-v15-35","title":"回用率與淨淡水耗用：試驗與驗證","titleEn":"Reuse ratio and net freshwater use: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「回用率與淨淡水耗用」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Reuse ratio and net freshwater use” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。以完整週期的池位回復確認沒有借用下一循環庫容，將蒸發漏流另列為水源負擔。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map every water source and destination, separating basins, sea and freshwater lake into control volumes. Cover a complete cycle and state whether vessel displacement is included in the metering boundary. Confirm basin-level recovery over a complete cycle to exclude borrowing future storage and list evaporation and leakage separately. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以回用率與淨淡水耗用編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。","observationEn":"Site practice: Prepare a reviewable evidence sheet for reuse ratio and net freshwater use, recording data time, units, model applicability and reviewer. Map every water source and destination, separating basins, sea and freshwater lake into control volumes. Cover a complete cycle and state whether vessel displacement is included in the metering boundary.","failure":"注意干擾：只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Quoting reuse alone confuses cycle hydraulics with watershed savings. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-35-k1","title":"驗證方法","titleEn":"Verification method","text":"為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。以完整週期的池位回復確認沒有借用下一循環庫容，將蒸發漏流另列為水源負擔。","textEn":"Map every water source and destination, separating basins, sea and freshwater lake into control volumes. Cover a complete cycle and state whether vessel displacement is included in the metering boundary. Confirm basin-level recovery over a complete cycle to exclude borrowing future storage and list evaporation and leakage separately.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-35-k2","title":"現場實務","titleEn":"Site practice","text":"以回用率與淨淡水耗用編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。","textEn":"Prepare a reviewable evidence sheet for reuse ratio and net freshwater use, recording data time, units, model applicability and reviewer. Map every water source and destination, separating basins, sea and freshwater lake into control volumes. Cover a complete cycle and state whether vessel displacement is included in the metering boundary.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「回用率與淨淡水耗用」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Reuse ratio and net freshwater use\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","慢速改變流量也必須產生完整的快速水錘壓峰。","為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A slow flow change must generate the full rapid-waterhammer pressure peak.","Map every water source and destination, separating basins, sea and freshwater lake into control volumes."],"answer":2,"explanation":"為每個水量畫清楚來源與去向，將暫存池、外海與淡水湖分成控制體；確認計量時間覆蓋完整循環，並說明船舶排水體積是否納入。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map every water source and destination, separating basins, sea and freshwater lake into control volumes. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":59},{"id":"b226-v15-36","title":"回用率與淨淡水耗用：失效診斷","titleEn":"Reuse ratio and net freshwater use: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-35"],"objective":"從症狀倒推「回用率與淨淡水耗用」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Reuse ratio and net freshwater use” and propose discriminating checks, corrective actions and prevention.","instruction":"只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。閘次船型差異和不完整循環又可能造成看似改善卻不可比較的績效數字。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Quoting reuse alone confuses cycle hydraulics with watershed savings. Vessel differences and incomplete cycles can produce apparently improved performance values that are not comparable across the measurement period. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：閘次船型差異和不完整循環又可能造成看似改善卻不可比較的績效數字。","observationEn":"Link to the mechanism: Vessel differences and incomplete cycles can produce apparently improved performance values that are not comparable across the measurement period.","failure":"誤判風險：若相信「百分之六十回用一定讓全年淡水需求直接減少六成。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Sixty percent reuse necessarily reduces annual freshwater demand by sixty percent.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-36-k1","title":"失效模式","titleEn":"Failure mode","text":"只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。閘次船型差異和不完整循環又可能造成看似改善卻不可比較的績效數字。","textEn":"Quoting reuse alone confuses cycle hydraulics with watershed savings. Vessel differences and incomplete cycles can produce apparently improved performance values that are not comparable across the measurement period.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「回用率與淨淡水耗用」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Reuse ratio and net freshwater use\" shows distress, which diagnosis is most reasonable?","options":["只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","設備修復後，積壓通行一定能按機械最大吞吐量完成。"],"optionsEn":["Quoting reuse alone confuses cycle hydraulics with watershed savings.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","After repair the backlog can always clear at maximum mechanical throughput."],"answer":0,"explanation":"只引用回用率而省略其他損失，會把單次水力效率誤當流域節水。 需以量測區分可能原因。","explanationEn":"Quoting reuse alone confuses cycle hydraulics with watershed savings. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":60},{"id":"b226-v15-37","title":"故障停航與水源緩衝：機制與系統路徑","titleEn":"Outage backlog and water reserve: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-36"],"objective":"說明「故障停航與水源緩衝」如何影響巴拿馬運河擴建新船閘的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Outage backlog and water reserve” governs forces, deformation, flow or signals in “Panama Canal expansion locks”, and map the relevant inputs, transfer paths and boundaries.","instruction":"容量與水源限制可能交互作用，故障後即使機械恢復，也需要足夠淡水與航道時間清理隊列。系統復原應同時盤點通行和水量資源。 假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³；若可分配水量每日170000 m³，至少需4 days，不含新增需求。 機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。若水位下降又增加抽水或通航限制，簡單固定單次需求亦會改變。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「故障停航與水源緩衝」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Capacity and water availability interact: after mechanical restoration, clearing a backlog also needs freshwater and navigation time. Recovery therefore requires both transit and water-resource accounting. Assume eight queued transits each needing teaching makeup 85000 m³. Extra demand is 680000 m³; allocation 170000 m³/day requires at least four days, excluding new arrivals. Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible. Falling levels can introduce further pumping or navigation constraints and change the assumed fixed water demand per transit. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Outage backlog and water reserve” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：教學假設，非地標實測值或操作設定：假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³；若可分配水量每日170000 m³，至少需4 days，不含新增需求。","observationEn":"Order-of-magnitude cue: Teaching assumptions, not landmark measurements or operating settings: Assume eight queued transits each needing teaching makeup 85000 m³.","failure":"常見誤解：「設備修復後，積壓通行一定能按機械最大吞吐量完成。」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"After repair the backlog can always clear at maximum mechanical throughput.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「故障停航與水源緩衝」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Outage backlog and water reserve”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b226-v15-37-k1","title":"故障停航與水源緩衝","titleEn":"Outage backlog and water reserve","text":"容量與水源限制可能交互作用，故障後即使機械恢復，也需要足夠淡水與航道時間清理隊列。系統復原應同時盤點通行和水量資源。","textEn":"Capacity and water availability interact: after mechanical restoration, clearing a backlog also needs freshwater and navigation time. Recovery therefore requires both transit and water-resource accounting.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：設備修復後，積壓通行一定能按機械最大吞吐量完成。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: After repair the backlog can always clear at maximum mechanical throughput. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"關於「故障停航與水源緩衝」，下列哪一項敘述正確？","questionEn":"Which statement about \"Outage backlog and water reserve\" is correct?","options":["設備修復後，積壓通行一定能按機械最大吞吐量完成。","容量與水源限制可能交互作用，故障後即使機械恢復，也需要足夠淡水與航道時間清理隊列。","節水池即使面積有限，交換水量時水位仍保持不變。"],"optionsEn":["After repair the backlog can always clear at maximum mechanical throughput.","Capacity and water availability interact: after mechanical restoration, clearing a backlog also needs freshwater and navigation time.","A finite saving basin maintains constant level while exchanging water."],"answer":1,"explanation":"容量與水源限制可能交互作用，故障後即使機械恢復，也需要足夠淡水與航道時間清理隊列。 其餘選項是常見誤解。","explanationEn":"Capacity and water availability interact: after mechanical restoration, clearing a backlog also needs freshwater and navigation time. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":61},{"id":"b226-v15-38","title":"故障停航與水源緩衝：定量估算","titleEn":"Outage backlog and water reserve: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-37"],"objective":"以數值模型估算「故障停航與水源緩衝」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Outage backlog and water reserve” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：教學假設，非地標實測值或操作設定：假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³；若可分配水量每日170000 m³，至少需4 days，不含新增需求。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Teaching assumptions, not landmark measurements or operating settings: Assume eight queued transits each needing teaching makeup 85000 m³. Extra demand is 680000 m³; allocation 170000 m³/day requires at least four days, excluding new arrivals. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。","observationEn":"How to cross-check: Build a common calendar of anonymous transit queues, available water and other withdrawals.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b226-v15-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"教學假設，非地標實測值或操作設定：假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³；若可分配水量每日170000 m³，至少需4 days，不含新增需求。","textEn":"Teaching assumptions, not landmark measurements or operating settings: Assume eight queued transits each needing teaching makeup 85000 m³. Extra demand is 680000 m³; allocation 170000 m³/day requires at least four days, excluding new arrivals.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"依「故障停航與水源緩衝」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Outage backlog and water reserve\", which statement holds?","options":["閘室平均水位平穩就表示船首船尾沒有壓力差。","平均輪載足夠低就能排除任何個別輪組超載。","教學假設，非地標實測值或操作設定：假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³。"],"optionsEn":["A steady mean chamber level means there is no bow-to-stern pressure difference.","Low mean wheel load rules out overload in every individual wheel group.","Teaching assumptions, not landmark measurements or operating settings: Assume eight queued transits each needing teaching makeup 85000 m³."],"answer":2,"explanation":"教學假設，非地標實測值或操作設定：假設積壓8次通行、每次教學補水85000 m³，額外需求680000 m³；若可分配水量每日170000 m³，至少需4 days，不含新增需求。 重算時請保留單位。","explanationEn":"Teaching assumptions, not landmark measurements or operating settings: Assume eight queued transits each needing teaching makeup 85000 m³. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":62},{"id":"b226-v15-39","title":"故障停航與水源緩衝：試驗與驗證","titleEn":"Outage backlog and water reserve: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「故障停航與水源緩衝」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Outage backlog and water reserve” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。將每天新增通行需求加入排程重算，檢查水源可分配量是否仍足以逐日減少積壓。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Build a common calendar of anonymous transit queues, available water and other withdrawals. Separate confirmed supply constraints from adjustable schedules and check that demands are not counted twice. Add newly arriving demand to the daily schedule and check whether allocated water still reduces the backlog each day. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以故障停航與水源緩衝編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。","observationEn":"Site practice: Prepare a reviewable evidence sheet for outage backlog and water reserve, recording data time, units, model applicability and reviewer. Build a common calendar of anonymous transit queues, available water and other withdrawals. Separate confirmed supply constraints from adjustable schedules and check that demands are not counted twice.","failure":"注意干擾：機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b226-v15-39-k1","title":"驗證方法","titleEn":"Verification method","text":"用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。將每天新增通行需求加入排程重算，檢查水源可分配量是否仍足以逐日減少積壓。","textEn":"Build a common calendar of anonymous transit queues, available water and other withdrawals. Separate confirmed supply constraints from adjustable schedules and check that demands are not counted twice. Add newly arriving demand to the daily schedule and check whether allocated water still reduces the backlog each day.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-39-k2","title":"現場實務","titleEn":"Site practice","text":"以故障停航與水源緩衝編製可交接的證據頁，註明資料時間、單位、模型適用範圍與審查者。用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。","textEn":"Prepare a reviewable evidence sheet for outage backlog and water reserve, recording data time, units, model applicability and reviewer. Build a common calendar of anonymous transit queues, available water and other withdrawals. Separate confirmed supply constraints from adjustable schedules and check that demands are not counted twice.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"要驗證「故障停航與水源緩衝」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Outage backlog and water reserve\"?","options":["用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。","不確定度太難估計，報告中只寫最佳值即可。","兩澆塊最高溫度相同就表示熱裂縫風險完全相同。"],"optionsEn":["Build a common calendar of anonymous transit queues, available water and other withdrawals.","Uncertainty is too hard to estimate, so the report may state only the best value.","Two blocks with the same peak temperature have identical thermal-cracking risk."],"answer":0,"explanation":"用匿名化通行隊列、可分配水量與其他取水用途建立共同日曆；將已確認的供水約束和可調整排程分開，核對每項需求是否重複計列。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Build a common calendar of anonymous transit queues, available water and other withdrawals. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":63},{"id":"b226-v15-40","title":"故障停航與水源緩衝：失效診斷","titleEn":"Outage backlog and water reserve: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"],"prerequisiteIds":["b226-v15-39"],"objective":"從症狀倒推「故障停航與水源緩衝」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Outage backlog and water reserve” and propose discriminating checks, corrective actions and prevention.","instruction":"機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。若水位下降又增加抽水或通航限制，簡單固定單次需求亦會改變。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible. Falling levels can introduce further pumping or navigation constraints and change the assumed fixed water demand per transit. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：若水位下降又增加抽水或通航限制，簡單固定單次需求亦會改變。","observationEn":"Link to the mechanism: Falling levels can introduce further pumping or navigation constraints and change the assumed fixed water demand per transit.","failure":"誤判風險：若相信「設備修復後，積壓通行一定能按機械最大吞吐量完成。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"After repair the backlog can always clear at maximum mechanical throughput.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b226-v15-40-k1","title":"失效模式","titleEn":"Failure mode","text":"機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。若水位下降又增加抽水或通航限制，簡單固定單次需求亦會改變。","textEn":"Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible. Falling levels can introduce further pumping or navigation constraints and change the assumed fixed water demand per transit.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]},{"id":"b226-v15-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v15s-acp-open","v7-panama-basins","v7-panama-expanded","v15s-usace-steel","v15s-usace-mechanical"]}],"quiz":{"question":"在「故障停航與水源緩衝」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Outage backlog and water reserve\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。","節水池即使面積有限，交換水量時水位仍保持不變。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible.","A finite saving basin maintains constant level while exchanging water."],"answer":1,"explanation":"機械最大吞吐量可能遠高於水源允許速率，忽略這點會提出無法實現的復原計畫。 需以量測區分可能原因。","explanationEn":"Mechanical throughput can exceed water-limited capacity, making a recovery plan infeasible. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":64}],"order":9}],"curriculumVersion":7,"enrichmentVersion":15,"learningTrack":"water","learningSubdiscipline":"water-systems","learningTags":["water","water-systems","water"],"subcategory":"water-systems","subcategoryTitle":"防潮、航運與大壩施工","subcategoryTitleEn":"Tidal barriers, navigation and dam construction","v15Architecture":{"architectureFamily":"water-lock","architectureNodes":[["雙池水位均衡","Equalization between two pools"],["縱向水面坡度推力","Longitudinal water-slope force"],["閘門浮力與輪載","Gate buoyancy and wheel loads"],["混凝土溫差拘束","Concrete thermal restraint"],["故障停航與水源緩衝","Outage backlog and water reserve"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,1]]},"v15Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"本課原創比較練習分兩個相互獨立的物理模型。教學假設，非地標實測值或操作設定：假設閘室面積20000 m²、水位10 m，池面積10000 m²、水位4 m，同基準且斷面固定；均衡水位(20000×10+10000×4)/30000=8 m。教學假設，非地標實測值或操作設定：假設三角形充水歷線峰值300 m³/s、總歷時1200 s，水量0.5Qt=180000 m³；閘面積22500 m²則升8 m，非本站運轉歷線。先逐一圈出公式內的控制體、力方向或時間尺度，再把每項輸入的量綱換成一致單位。第二人只根據輸入重算結果，不抄第一人的中間數字。最後指出這兩個估算尚未包含的空間變化、非線性及量測誤差；若將結果用於另一座工程，必須重建其幾何、材料與邊界條件，不能挪用本練習的假設。 均衡水位的單參數比較固定閘室面積20000 m²、初始水位10 m及池面積10000 m²，只將池初始水位由4升至6 m。同基準下最終水位由8 m升為(20000×10+10000×6)/30000=8.6667 m；池升2 m只令共同水位升0.6667 m。這是兩固定面積水體的封閉體積平衡，未計船舶移動、漏水或外部補水。","textEn":"This original comparison exercise uses two independent physical models. Teaching assumptions, not landmark measurements or operating settings: Assume chamber area 20000 m² at level 10 m and basin area 10000 m² at 4 m, common datum and fixed areas. Equalized level is (20000×10+10000×4)/30000=8 m. Teaching assumptions, not landmark measurements or operating settings: Assume triangular filling hydrograph with peak 300 m³/s over 1200 s. Volume is 180000 m³ and rise over 22500 m² is 8 m, not a site operating hydrograph. First identify the control volume, force direction or time scale in each relation, then convert every input to consistent units. A second reviewer recalculates from the inputs without copying intermediate numbers. Finally identify spatial variability, nonlinear effects and measurement errors omitted by both estimates. Transfer to another structure requires rebuilding its geometry, material description and boundary conditions; the assumed classroom inputs are not transferable design or operating parameters. For equalization sensitivity, keep chamber area 20000 m², initial chamber level 10 m and basin area 10000 m² fixed, raising only initial basin level from 4 m to 6 m. On the common datum, final level rises from 8 m to (20000×10+10000×6)/30000=8.6667 m. A 2 m basin change raises the common level only 0.6667 m. This closed-volume comparison excludes vessel movement, leakage and external supply.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"節水池耦合、非恆定充洩水與滾動閘門的定量深化","focusEn":"Quantitative extension of basin coupling, unsteady filling and rolling-gate mechanics"}}};
